package game29

// ── P2P exchange: escrowed limit-order book (any coin pair) ──────────────────
//
// A maker escrows `give` and asks for `want` at their own price; takers fill
// at the maker's price (fully or partly). Cancel or expiry refunds the
// remaining escrow; the 2-grin posting fee is not refunded. No price bands.
//
// Storage (≈ 200 bytes per open order): no per-order tree node (one avl
// insert costs ~2.1 KB of storage deposit). Each maker has ONE compact string
// holding their ≤ 20 open orders, and each book side (want>give) is ONE
// fixed-width string of sorted 76-byte entries (priceKey24 + id12 + maker40),
// capped at maxSideOrders; when a side is full a new order must beat the
// worst one, which is then refunded to its maker (evicted).

import (
	"std"
	"math/bits"
	"strconv"
	"strings"
	"time"
)

type order struct {
	id               uint64
	maker            string
	give, want       string
	remGive, remWant uint64
	expiry           int64
	pk               string // price key part of the book key
}

func padU(n uint64, w int) string {
	s := strconv.FormatUint(n, 10)
	for len(s) < w {
		s = "0" + s
	}
	return s
}

const hexDigits = "0123456789abcdef"

// priceKey = want-per-give × 1e12 as a fixed-width 24-hex-digit number
// (96 bits; amounts ≤ 1e15 keep it < 2^90). Lexicographic = numeric order,
// so ascending book keys are the cheapest asks first for takers.
func priceKey(wantAmt, giveAmt uint64) string {
	hi, lo := bits.Mul64(wantAmt, 1000000000000)
	qhi := hi / giveAmt
	qlo, _ := bits.Div64(hi%giveAmt, lo, giveAmt)
	if qhi >= 1<<32 {
		panic("price out of range")
	}
	b := make([]byte, 24)
	for i := 7; i >= 0; i-- {
		b[i] = hexDigits[qhi&15]
		qhi >>= 4
	}
	for i := 23; i >= 8; i-- {
		b[i] = hexDigits[qlo&15]
		qlo >>= 4
	}
	return string(b)
}

const (
	sideEntryLen  = 76  // priceKey(24) + id(12) + maker address(40)
	sideSortLen   = 36  // entries sort by priceKey then id (FIFO within a price)
	maxSideOrders = 256 // open orders per book side; bounds every string we rewrite
)

// maker record: id12|give|want|remGive|remWant|expiry|pk
func encodeOrder(o *order) string {
	return padU(o.id, 12) + "|" + o.give + "|" + o.want + "|" + u(o.remGive) + "|" + u(o.remWant) + "|" +
		strconv.FormatInt(o.expiry, 10) + "|" + o.pk
}

func decodeOrder(maker, rec string) *order {
	f := strings.Split(rec, "|")
	if len(f) != 7 {
		panic("corrupt order")
	}
	id, _ := strconv.ParseUint(f[0], 10, 64)
	rg, _ := strconv.ParseUint(f[3], 10, 64)
	rw, _ := strconv.ParseUint(f[4], 10, 64)
	ex, _ := strconv.ParseInt(f[5], 10, 64)
	return &order{id: id, maker: maker, give: f[1], want: f[2], remGive: rg, remWant: rw, expiry: ex, pk: f[6]}
}

func makerRecs(maker string) []string {
	if !makerBooks.Has(maker) {
		return nil
	}
	v := makerBooks.Get(maker).(string)
	if v == "" {
		return nil
	}
	return strings.Split(v, ";")
}

func setMakerRecs(maker string, recs []string) {
	if len(recs) == 0 {
		makerBooks.Remove(maker)
		return
	}
	makerBooks.Set(maker, strings.Join(recs, ";"))
}

// loadOrderOf finds one of maker's open orders (≤ 20 records scanned).
func loadOrderOf(maker string, id uint64) *order {
	pre := padU(id, 12) + "|"
	for _, r := range makerRecs(maker) {
		if strings.HasPrefix(r, pre) {
			return decodeOrder(maker, r)
		}
	}
	return nil
}

func saveOrder(o *order) {
	recs := makerRecs(o.maker)
	pre := padU(o.id, 12) + "|"
	for i, r := range recs {
		if strings.HasPrefix(r, pre) {
			recs[i] = encodeOrder(o)
			setMakerRecs(o.maker, recs)
			return
		}
	}
	panic("invariant: order not found")
}

func sideKey(want, give string) string { return want + ">" + give }

func sideEntry(o *order) string { return o.pk + padU(o.id, 12) + o.maker }

func sideStr(k string) string {
	if !sides.Has(k) {
		return ""
	}
	return sides.Get(k).(string)
}

// sideSearch returns the index of the first entry whose sort key is ≥ key.
func sideSearch(s, key string) int {
	lo, hi := 0, len(s)/sideEntryLen
	for lo < hi {
		mid := (lo + hi) / 2
		if s[mid*sideEntryLen:mid*sideEntryLen+sideSortLen] < key {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

func sideInsert(o *order) {
	k := sideKey(o.want, o.give)
	s := sideStr(k)
	e := sideEntry(o)
	i := sideSearch(s, e[:sideSortLen]) * sideEntryLen
	sides.Set(k, s[:i]+e+s[i:])
}

func sideRemove(o *order) {
	k := sideKey(o.want, o.give)
	s := sideStr(k)
	e := sideEntry(o)
	i := sideSearch(s, e[:sideSortLen]) * sideEntryLen
	if i+sideEntryLen > len(s) || s[i:i+sideEntryLen] != e {
		panic("invariant: book entry missing")
	}
	s = s[:i] + s[i+sideEntryLen:]
	if s == "" {
		sides.Remove(k)
	} else {
		sides.Set(k, s)
	}
}

// iterSide walks a taker's side (pays `pay`, gets `get`) best price first.
func iterSide(pay, get string, fn func(maker string, id uint64) bool) {
	s := sideStr(sideKey(pay, get))
	for i := 0; i+sideEntryLen <= len(s); i += sideEntryLen {
		e := s[i : i+sideEntryLen]
		id, _ := strconv.ParseUint(e[24:36], 10, 64)
		if fn(e[36:], id) {
			return
		}
	}
}

func sideCount(pay, get string) int { return len(sideStr(sideKey(pay, get))) / sideEntryLen }

// grinValueMilli = amt × reference value (milli-grin), saturating at 2^64-1.
func grinValueMilli(coin string, amt uint64) uint64 {
	hi, lo := bits.Mul64(amt, prefMilli[requireCoin(coin)])
	if hi != 0 {
		return ^uint64(0)
	}
	return lo
}

func openOrderCount(maker string) uint64 { return uint64(len(makerRecs(maker))) }

// PlaceOrder escrows giveAmt of `give` and lists it for wantAmt of `want`
// (any pair). Costs 2 grin (protocol fee, not refunded). Returns the id.
// expirySecs 0 = 72 h; max 7 days.
func PlaceOrder(cur realm, give string, giveAmt uint64, want string, wantAmt uint64, expirySecs int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireCoin(give)
	requireCoin(want)
	if give == want {
		panic("give and want must differ")
	}
	requireAmount("giveAmt", giveAmt)
	requireAmount("wantAmt", wantAmt)
	if grinValueMilli(give, giveAmt) < minOrderGrinX1k {
		panic("order too small: minimum is 50 grin of value")
	}
	if expirySecs == 0 {
		expirySecs = defaultExpiry
	}
	if expirySecs < 60 || expirySecs > maxExpiry {
		panic("expiry must be between 60 s and 7 days")
	}
	if openOrderCount(caller) >= maxOpenOrders {
		panic("max 20 open orders")
	}
	if len(caller) != 40 {
		panic("invalid maker address")
	}
	pk := priceKey(wantAmt, giveAmt)
	nextId := addChk(nextOrderId, 1)
	// A full side only takes an order that beats its worst one (which is then
	// refunded to its maker): spam can't lock the book with absurd prices.
	var evict *order
	if sideCount(want, give) >= maxSideOrders {
		s := sideStr(sideKey(want, give))
		w := s[len(s)-sideEntryLen:]
		if pk+padU(nextId, 12) >= w[:sideSortLen] {
			panic("book side full: price must beat the worst open order")
		}
		wid, _ := strconv.ParseUint(w[24:36], 10, 64)
		evict = loadOrderOf(w[36:], wid)
		if evict == nil {
			panic("invariant: book entry without order")
		}
	}
	if give == hubCoin {
		requireBalance(caller, hubCoin, addChk(giveAmt, postFeeGrin))
	} else {
		requireBalance(caller, hubCoin, postFeeGrin)
		requireBalance(caller, give, giveAmt)
	}
	// ── all checks passed; writes start here ──
	debitBal(caller, hubCoin, postFeeGrin)
	accrueProtocolFee(hubCoin, postFeeGrin)
	debitBal(caller, give, giveAmt) // escrow

	if evict != nil {
		closeOrder(evict, "evicted")
	}
	nextOrderId = nextId
	o := &order{id: nextId, maker: caller, give: give, want: want, remGive: giveAmt, remWant: wantAmt,
		expiry: time.Now().Unix() + expirySecs, pk: pk}
	setMakerRecs(caller, append(makerRecs(caller), encodeOrder(o)))
	sideInsert(o)
	openOrderTotal = addChk(openOrderTotal, 1)
	std.Emit("OrderPlaced", "id", u(o.id), "maker", caller, "give", give, "giveAmt", u(giveAmt),
		"want", want, "wantAmt", u(wantAmt), "expiry", strconv.FormatInt(o.expiry, 10))
	return o.id
}

// closeOrder refunds the remaining escrow to the MAKER (never anyone else)
// and deletes the order. Every close path goes through here.
func closeOrder(o *order, reason string) {
	refund := o.remGive
	if refund > 0 {
		creditBal(o.maker, o.give, refund)
		o.remGive = 0
	}
	sideRemove(o)
	recs := makerRecs(o.maker)
	pre := padU(o.id, 12) + "|"
	for i, r := range recs {
		if strings.HasPrefix(r, pre) {
			recs = append(recs[:i], recs[i+1:]...)
			break
		}
	}
	setMakerRecs(o.maker, recs)
	openOrderTotal = subChk(openOrderTotal, 1)
	std.Emit("OrderClosed", "id", u(o.id), "maker", o.maker, "reason", reason, "refund", u(refund))
}

// CancelOrder: the maker gets the remaining escrow back. Works while paused
// and for banned makers; only the maker can cancel.
func CancelOrder(cur realm, id uint64) {
	caller := exchangeCaller(cur)
	// Lookup is by the caller's own orders only: nobody can name someone
	// else's order here.
	o := loadOrderOf(caller, id)
	if o == nil {
		panic("no such open order (or not your order)")
	}
	closeOrder(o, "cancel")
}

// SweepExpiredOrders closes up to maxScanPerTx expired orders of one book
// side, refunding each maker. Anyone may call it (also while paused).
func SweepExpiredOrders(cur realm, pay string, get string) int {
	exchangeCaller(cur)
	now := time.Now().Unix()
	var expired []*order
	scanned := 0
	iterSide(pay, get, func(maker string, id uint64) bool {
		scanned++
		if scanned > maxScanPerTx {
			return true
		}
		o := loadOrderOf(maker, id)
		if o != nil && o.expiry < now {
			expired = append(expired, o)
		}
		return false
	})
	for _, o := range expired {
		closeOrder(o, "expired")
	}
	return len(expired)
}

type fillStep struct {
	o    *order
	x, g uint64 // taker pays x (+fee) of `pay`, receives g of `get`
}

// planFills walks the book for a taker (read-only). budget is the most the
// taker will spend INCLUDING the taker fee. Own orders are skipped (no
// self-match); expired orders are returned for closing.
func planFills(caller, pay, get string, budget uint64, maxFills int, now int64) ([]fillStep, []*order, uint64, uint64) {
	if maxFills <= 0 || maxFills > maxFillsPerTx {
		maxFills = maxFillsPerTx
	}
	var steps []fillStep
	var expired []*order
	remaining := budget
	spent, got := uint64(0), uint64(0)
	scanned := 0
	iterSide(pay, get, func(maker string, id uint64) bool {
		scanned++
		if scanned > maxScanPerTx || len(steps) >= maxFills || remaining == 0 {
			return true
		}
		o := loadOrderOf(maker, id)
		if o == nil {
			return false
		}
		if o.expiry < now {
			expired = append(expired, o)
			return false
		}
		if o.maker == caller {
			return false // no self-match: skip, never touch the taker's own order
		}
		// largest x with x + ceil(x × takerFee) ≤ remaining
		x := mulDiv(remaining, 10000, 10000+takerFeeBps)
		for i := 0; i < 4 && x > 0 && addChk(x, mulDivUp(x, takerFeeBps, 10000)) > remaining; i++ {
			x--
		}
		if x > o.remWant {
			x = o.remWant
		}
		if x == 0 {
			return true
		}
		g := o.remGive
		if x < o.remWant {
			g = mulDiv(x, o.remGive, o.remWant) // floor: the maker never sells below their price
		}
		if g == 0 {
			return true
		}
		cost := addChk(x, mulDivUp(x, takerFeeBps, 10000))
		steps = append(steps, fillStep{o: o, x: x, g: g})
		remaining = subChk(remaining, cost)
		spent = addChk(spent, cost)
		got = addChk(got, g)
		return false
	})
	return steps, expired, spent, got
}

// executeFills applies a plan: the taker pays each maker x and the protocol
// fee, receives g from escrow. Returns the total received.
func executeFills(caller, pay string, steps []fillStep) uint64 {
	got := uint64(0)
	for _, st := range steps {
		o := st.o
		fee := mulDivUp(st.x, takerFeeBps, 10000)
		debitBal(caller, pay, addChk(st.x, fee))
		accrueProtocolFee(pay, fee)
		creditBal(o.maker, pay, st.x)
		o.remWant = subChk(o.remWant, st.x)
		o.remGive = subChk(o.remGive, st.g)
		got = addChk(got, st.g)
		std.Emit("OrderFilled", "id", u(o.id), "maker", o.maker, "taker", caller,
			"paid", u(st.x), "fee", u(fee), "got", u(st.g))
		if o.remWant == 0 || o.remGive == 0 {
			closeOrder(o, "filled")
		} else if grinValueMilli(o.give, o.remGive) < minOrderGrinX1k {
			closeOrder(o, "dust")
		} else {
			saveOrder(o)
		}
	}
	return got
}

// FillOrders: spend at most payAmt of `pay` (taker fee included) on the
// best-priced orders that give `get`; receive at least minGet or revert.
// ≤ 10 fills and ≤ 20 scanned entries per call.
func FillOrders(cur realm, pay string, get string, payAmt uint64, minGet uint64, maxFills int, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireCoin(pay)
	requireCoin(get)
	requireAmount("payAmt", payAmt)
	steps, expired, spent, planned := planFills(caller, pay, get, payAmt, maxFills, time.Now().Unix())
	if planned == 0 || planned < minGet {
		panic("slippage: received below minimum")
	}
	requireBalance(caller, pay, spent)
	// ── all checks passed; writes start here ──
	for _, o := range expired {
		closeOrder(o, "expired")
	}
	got := executeFills(caller, pay, steps)
	if got != planned {
		panic("invariant: fill plan mismatch")
	}
	creditBal(caller, get, got)
	return got
}

// ── views ────────────────────────────────────────────────────────────────────

func orderJSON(o *order) string {
	return `{"id":"` + u(o.id) + `","maker":"` + o.maker + `","give":` + jsonStr(o.give) + `,"want":` + jsonStr(o.want) +
		`,"remGive":"` + u(o.remGive) + `","remWant":"` + u(o.remWant) + `","expiry":` + strconv.FormatInt(o.expiry, 10) + `}`
}

// Order shows one open order of `maker` (lookups are per maker by design).
func Order(maker string, id uint64) string {
	o := loadOrderOf(maker, id)
	if o == nil {
		return `{"id":"` + u(id) + `","open":false}`
	}
	return orderJSON(o)
}

// OrdersOf lists an address's open orders (≤ 20 by construction).
func OrdersOf(addr string) string {
	out := "["
	for i, r := range makerRecs(addr) {
		if i > 0 {
			out += ","
		}
		out += orderJSON(decodeOrder(addr, r))
	}
	return out + "]"
}

// BookDepth lists asks for a taker who pays `pay` and gets `get`, best price
// first (≤ 50 rows; offset < maxSideOrders).
func BookDepth(pay string, get string, limit int, offset int) string {
	if limit <= 0 || limit > maxViewLimit {
		limit = maxViewLimit
	}
	if offset < 0 || offset >= maxSideOrders {
		offset = 0
	}
	out := "["
	i, n := 0, 0
	iterSide(pay, get, func(maker string, id uint64) bool {
		if i < offset {
			i++
			return false
		}
		if o := loadOrderOf(maker, id); o != nil {
			if n > 0 {
				out += ","
			}
			out += orderJSON(o)
			n++
		}
		return n >= limit
	})
	return out + "]"
}

// QuoteFill previews FillOrders for a budget (fee included): {"spent","got"}.
func QuoteFill(caller string, pay string, get string, payAmt uint64, maxFills int) string {
	if payAmt == 0 || payAmt > maxAmount {
		return `{"spent":"0","got":"0","fills":0}`
	}
	steps, _, spent, got := planFills(caller, pay, get, payAmt, maxFills, time.Now().Unix())
	return `{"spent":"` + u(spent) + `","got":"` + u(got) + `","fills":` + strconv.Itoa(len(steps)) + `}`
}

package game29

// ── P2P exchange: core (docs/P2P_EXCHANGE_PLAN.md, docs/EXCHANGE_SECURITY_REVIEW.md)
//
// Open economy (Simion, 2026-10-11): no price-impact cap, no price bands, no
// reference-price checks on deposits. Every value-moving call takes the
// trader's own protection instead: a minimum output (minOut / minShares /
// minGet) and a deadline.
//
// Security rules this file enforces for the whole exchange:
//   - The exchange only moves coins that already exist in `balances`
//     (debitBal → reserves/escrow → creditBal). It never mints.
//   - The admin has NO path to pool reserves, LP positions, escrowed orders,
//     accrued casino fees or player balances. Admin powers are listed in
//     docs/EXCHANGE_SECURITY_REVIEW.md §2.
//   - Pause stops only NEW swaps / orders / deposits. Exits — RemoveLiquidity,
//     CancelOrder, SweepExpiredOrders, WithdrawProtocolFees — always work,
//     also while paused and for banned addresses.
//   - All amounts are uint64; every add/mul is checked (panics, never wraps);
//     products use 128-bit intermediates; rounding favors the pool / maker.
//   - No exchange path calls another realm or sends coins: no reentrancy.
//   - Loops are bounded by constants (≤ maxFillsPerTx fills, ≤ maxScanPerTx
//     scanned entries, ≤ maxViewLimit view rows, ≤ maxOpenOrders per maker).
//   - Block time is used only for deadlines, order expiry and the LP warm-up.

import (
	"std"
	"math/bits"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	hubCoin = "grin"

	// Pools: 0.50% of the input; 0.35% stays in the pool (LPs), 0.15% is the
	// protocol fee, split 50/50 between the admin and the casino pool.
	poolFeeBps  = uint64(50)
	protoFeeBps = uint64(15)

	minLiquidity     = uint64(1000) // first-deposit shares burned forever
	minOpenDepthGrin = uint64(2000) // a pool takes swaps only once rGrin ≥ this
	warmupSecs       = int64(600)   // LP fee warm-up (principal always instant)
	rootKScale       = uint64(1000000000)

	// Order book: makers 0%, takers 0.50% of what they pay, 2 grin per order.
	takerFeeBps     = uint64(50)
	postFeeGrin     = uint64(2)
	minOrderGrinX1k = uint64(50000) // 50 grin of value (reference table) — size floor only
	maxOpenOrders   = uint64(20)
	defaultExpiry   = int64(72 * 3600)
	maxExpiry       = int64(7 * 24 * 3600)
	maxFillsPerTx   = 10
	maxScanPerTx    = 20
	maxViewLimit    = 50

	// Upper bound for any single amount argument. Keeps every intermediate far
	// from uint64 limits (balances are uint64 too) and rejects absurd inputs.
	maxAmount = uint64(1000000000000000) // 1e15

)

// Reference value per rarity in milli-grin (RARITY_VALUE ×1000). Used ONLY
// for the 50-grin minimum order size — never for prices.
var prefMilli = [7]uint64{1000, 3200, 11000, 40000, 160000, 720000, 3600000}

var (
	pools       avl.Tree // coin → *pool
	lpPositions avl.Tree // coin+":"+addr → *lpPos
	adminFees   avl.Tree // coin → admin's accrued protocol fees (pull)
	casinoPool  avl.Tree // coin → casino pool balance (fees in, capped jackpots out)
	makerBooks     avl.Tree // maker → ";"-joined compact order records (≤ maxOpenOrders)
	sides          avl.Tree // want+">"+give → sorted fixed-width entries (≤ maxSideOrders)
	openOrderTotal uint64
	nextOrderId    uint64
	exPaused    bool

	// Lifetime accounting (Render + audits).
	adminFeesWithdrawn avl.Tree // coin → lifetime withdrawn by the admin
	adminGnotWithdrawn int64    // ugnot withdrawn by WithdrawFunds (≤ passRevenueUgnot)
)

// ── checked math ─────────────────────────────────────────────────────────────

func addChk(a, b uint64) uint64 {
	s, carry := bits.Add64(a, b, 0)
	if carry != 0 {
		panic("math overflow")
	}
	return s
}

func subChk(a, b uint64) uint64 {
	if b > a {
		panic("math underflow")
	}
	return a - b
}

// mulDiv = floor(a*b/c) with a 128-bit product; panics if c == 0 or the
// quotient does not fit in 64 bits.
func mulDiv(a, b, c uint64) uint64 {
	if c == 0 {
		panic("division by zero")
	}
	hi, lo := bits.Mul64(a, b)
	if hi >= c {
		panic("math overflow")
	}
	q, _ := bits.Div64(hi, lo, c)
	return q
}

// mulDivUp = ceil(a*b/c).
func mulDivUp(a, b, c uint64) uint64 {
	if c == 0 {
		panic("division by zero")
	}
	hi, lo := bits.Mul64(a, b)
	if hi >= c {
		panic("math overflow")
	}
	q, r := bits.Div64(hi, lo, c)
	if r > 0 {
		q = addChk(q, 1)
	}
	return q
}

// isqrt128 = floor(sqrt(a*b)) for the 128-bit product (Newton, bounded).
func isqrt128(a, b uint64) uint64 {
	hi, lo := bits.Mul64(a, b)
	if hi == 0 {
		return isqrt(lo)
	}
	// sqrt of a 128-bit number < 2^64. Start above the root and descend.
	x := ^uint64(0)
	for i := 0; i < 200; i++ {
		if hi >= x { // product/x overflows ⇒ x below the root; cannot happen when descending from max
			panic("isqrt: bad state")
		}
		q, _ := bits.Div64(hi, lo, x)
		nx := (x >> 1) + (q >> 1) + (x & q & 1)
		if nx >= x {
			return x
		}
		x = nx
	}
	panic("isqrt: no convergence")
}

func isqrt(n uint64) uint64 {
	if n < 2 {
		return n
	}
	x := n
	y := x/2 + 1
	for i := 0; i < 200 && y < x; i++ {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// mulLess reports a*b < c*d using 128-bit products.
func mulLess(a, b, c, d uint64) bool {
	h1, l1 := bits.Mul64(a, b)
	h2, l2 := bits.Mul64(c, d)
	return h1 < h2 || (h1 == h2 && l1 < l2)
}

// requireBalance checks a balance before any write, so a failing call
// changes nothing (validate-then-write).
func requireBalance(addr, coin string, amt uint64) {
	if have := balOf(addr, coin); have < amt {
		panic("insufficient " + coin + ": need " + u(amt) + " have " + u(have))
	}
}

func requireAmount(name string, v uint64) {
	if v == 0 || v > maxAmount {
		panic(name + " must be between 1 and " + strconv.FormatUint(maxAmount, 10))
	}
}

func u(n uint64) string { return strconv.FormatUint(n, 10) }

// ── gates ────────────────────────────────────────────────────────────────────

// exchangeCaller returns the caller for exchange writes. Only end users (an
// EOA MsgCall or the user's own MsgRun) may trade: other realms can't act
// through the exchange, so there is no cross-realm call surface at all.
func exchangeCaller(cur realm) string {
	prev := cur.Previous()
	if prev.PkgPath() != "" {
		panic("exchange calls must come directly from a user")
	}
	return prev.Address().String()
}

// requireMarketOpen gates NEW activity (swaps, deposits, orders, fills).
// Trading opens only after FinalizeMigration: MigrateBatch SETs balances, so
// trading before that could duplicate or lose escrowed coins.
func requireMarketOpen(caller string) {
	if !migrationFinalized {
		panic("exchange opens after FinalizeMigration")
	}
	if exPaused {
		panic("exchange paused: new trades are off; unstake and cancel still work")
	}
	if isBlacklisted(caller) {
		panic("address banned")
	}
}

func requireDeadline(deadline int64) {
	if deadline <= 0 {
		panic("deadline required (unix seconds)")
	}
	if time.Now().Unix() > deadline {
		panic("deadline passed")
	}
}

func requireCoin(coin string) int {
	r, ok := coinRarity[coin]
	if !ok {
		panic("unknown coin id: " + coin)
	}
	return r
}

// Trading is open to every account (Simion, 2026-10-11): no tool requirement
// to swap, post, fill or stake. Anti-spam comes from the 50-grin order
// minimum, the 2-grin post fee, the 0.5% taker/pool fees, the 20-open-orders
// limit per maker and the 2,000-grin minimum pool depth.

// No receive cap (Simion, 2026-10-11): every coin is freely transferable and
// tradable, whatever tools the receiver owns.

// ── protocol fees ────────────────────────────────────────────────────────────

// accrueProtocolFee splits amt of coin 50/50: the floor half to the admin's
// fee ledger, the rest to the casino pool. Both stay inside the realm.
func accrueProtocolFee(coin string, amt uint64) {
	if amt == 0 {
		return
	}
	half := amt / 2
	if half > 0 {
		setU(&adminFees, coin, addChk(getU(&adminFees, coin), half))
	}
	setU(&casinoPool, coin, addChk(getU(&casinoPool, coin), amt-half))
	casStat(coin, "", "fees", amt-half)
	std.Emit("ProtocolFeesAccrued", "coin", coin, "admin", u(half), "casino", u(amt-half))
}

// WithdrawProtocolFees moves the admin's OWN accrued fees for `coin` into the
// admin's balance. It reads only adminFees (never reserves, escrow, the
// casino pool or anyone's balance) and works while paused.
func WithdrawProtocolFees(cur realm, coin string) uint64 {
	requireAdmin(cur)
	requireCoin(coin)
	amt := getU(&adminFees, coin)
	if amt == 0 {
		panic("no fees to withdraw for " + coin)
	}
	adminFees.Remove(coin)
	setU(&adminFeesWithdrawn, coin, addChk(getU(&adminFeesWithdrawn, coin), amt))
	to := admin.String()
	creditBal(to, coin, amt)
	std.Emit("ProtocolFeesWithdrawn", "coin", coin, "to", to, "amount", u(amt))
	return amt
}

// ── casino pool (fee share + losing stakes in, wins out; never minted) ─────
//
// casinoPool[coin]     total pool, including the reserved part
// casinoReserved[coin] sum of potential net payouts of unsettled bets
// casinoDay[coin]      "day:snapshot:paid:received" for the current UTC day
//
// A bet is accepted only if the pool can pay it in full: its potential net
// payout (= the stake, since a win pays 2×) is reserved at placement, so a
// reveal never pays partially and the pool can't go below zero.









// ── admin controls (launch only; none touch user funds) ──────────────────────

// SetExchangePaused stops NEW swaps, deposits, orders and fills. It can't
// stop RemoveLiquidity, CancelOrder, SweepExpiredOrders or fee withdrawals.
func SetExchangePaused(cur realm, p bool) {
	requireAdmin(cur)
	exPaused = p
	std.Emit("ExchangePaused", "paused", strconv.FormatBool(p))
}

func ExchangeStatus() string {
	return `{"open":` + strconv.FormatBool(migrationFinalized && !exPaused) +
		`,"paused":` + strconv.FormatBool(exPaused) +
		`,"finalized":` + strconv.FormatBool(migrationFinalized) +
		`,"pools":` + strconv.Itoa(pools.Size()) +
		`,"openOrders":` + strconv.FormatUint(openOrderTotal, 10) +
		`,"nextOrderId":"` + u(nextOrderId) + `"` +
		`,"poolFeeBps":` + u(poolFeeBps) + `,"protoFeeBps":` + u(protoFeeBps) +
		`,"takerFeeBps":` + u(takerFeeBps) + `,"postFeeGrin":` + u(postFeeGrin) +
		`,"minOpenDepthGrin":` + u(minOpenDepthGrin) + `,"warmupSecs":` + strconv.FormatInt(warmupSecs, 10) + `}`
}

func ProtocolFees(coin string) string {
	return `{"coin":` + jsonStr(coin) + `,"admin":"` + u(getU(&adminFees, coin)) +
		`","adminWithdrawn":"` + u(getU(&adminFeesWithdrawn, coin)) +
		`","casino":"` + u(getU(&casinoPool, coin)) + `"}`
}

package game29

// ── P2P exchange: COIN/GRIN constant-product pools ───────────────────────────
//
// Reserves are internal counters, never "the realm's balance": a Transfer or
// bank send to the realm address can't move them (no donation attack).
// Rounding: swap fee up, output down, minted shares down, withdrawals down —
// always in the pool's favor. k (and √k per share) never decreases on a swap.

import (
	"std"
	"strconv"
	"time"
)

type pool struct {
	coin        string
	rCoin, rHub uint64 // reserves (coin side, grin side)
	shares      uint64 // total shares, including the burned minLiquidity
	paused      bool   // per-pool: stops new swaps/deposits only
}

type lpPos struct {
	shares    uint64
	entryRKPS uint64 // √k per share × rootKScale at (share-weighted) entry
	depositTs int64  // share-weighted deposit time (warm-up clock)
}

func getPool(coin string) *pool {
	if !pools.Has(coin) {
		panic("no pool for " + coin)
	}
	return pools.Get(coin).(*pool)
}

func rootKPerShare(p *pool) uint64 {
	if p.shares == 0 {
		return 0
	}
	return mulDiv(isqrt128(p.rCoin, p.rHub), rootKScale, p.shares)
}

// CreatePool opens an empty COIN/GRIN pool (admin, per the launch schedule).
// It holds nothing until players deposit; the admin can't deposit for anyone,
// withdraw from it or close it.
func CreatePool(cur realm, coin string) {
	requireAdmin(cur)
	if coin == hubCoin {
		panic("grin is the hub coin: pools are COIN/GRIN")
	}
	requireCoin(coin)
	if pools.Has(coin) {
		panic("pool exists")
	}
	pools.Set(coin, &pool{coin: coin})
	std.Emit("PoolCreated", "coin", coin)
}

// SetPoolPaused stops new swaps and deposits on one pool. Withdrawals stay open.
func SetPoolPaused(cur realm, coin string, p bool) {
	requireAdmin(cur)
	getPool(coin).paused = p
	std.Emit("PoolPaused", "coin", coin, "paused", strconv.FormatBool(p))
}

// AddLiquidity deposits up to coinMax of `coin` and grinMax grin. The first
// deposit sets the price (open economy: any ratio) and burns minLiquidity
// shares; later deposits take the current ratio (never more than either cap).
// Reverts unless at least minShares are minted.
func AddLiquidity(cur realm, coin string, coinMax uint64, grinMax uint64, minShares uint64, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireAmount("coinMax", coinMax)
	requireAmount("grinMax", grinMax)
	p := getPool(coin)
	if p.paused {
		panic("pool paused")
	}
	var aCoin, aHub, minted uint64
	if p.shares == 0 {
		aCoin, aHub = coinMax, grinMax
		s := isqrt128(aCoin, aHub)
		if s <= minLiquidity {
			panic("first deposit too small: sqrt(coin×grin) must exceed 1000")
		}
		minted = s - minLiquidity
	} else {
		aHub = grinMax
		aCoin = mulDivUp(aHub, p.rCoin, p.rHub)
		if aCoin > coinMax {
			aCoin = coinMax
			aHub = mulDivUp(aCoin, p.rHub, p.rCoin)
		}
		s1 := mulDiv(aCoin, p.shares, p.rCoin)
		s2 := mulDiv(aHub, p.shares, p.rHub)
		minted = s1
		if s2 < minted {
			minted = s2
		}
		if minted == 0 {
			panic("deposit too small for one share")
		}
	}
	if minted < minShares {
		panic("slippage: shares below minimum")
	}
	requireBalance(caller, coin, aCoin)
	requireBalance(caller, hubCoin, aHub)
	// ── all checks passed; writes start here ──
	if p.shares == 0 {
		p.shares = addChk(minted, minLiquidity) // minLiquidity shares belong to nobody (burned)
	} else {
		p.shares = addChk(p.shares, minted)
	}
	debitBal(caller, coin, aCoin)
	debitBal(caller, hubCoin, aHub)
	p.rCoin = addChk(p.rCoin, aCoin)
	p.rHub = addChk(p.rHub, aHub)

	key := coin + ":" + caller
	now := time.Now().Unix()
	rk := rootKPerShare(p)
	if lpPositions.Has(key) {
		pos := lpPositions.Get(key).(*lpPos)
		tot := addChk(pos.shares, minted)
		pos.entryRKPS = addChk(mulDiv(pos.entryRKPS, pos.shares, tot), mulDivUp(rk, minted, tot))
		// share-weighted deposit time: a top-up restarts the warm-up in proportion.
		pos.depositTs = int64(addChk(mulDiv(uint64(pos.depositTs), pos.shares, tot), mulDivUp(uint64(now), minted, tot)))
		pos.shares = tot
	} else {
		lpPositions.Set(key, &lpPos{shares: minted, entryRKPS: rk, depositTs: now})
	}
	std.Emit("LiquidityAdded", "coin", coin, "who", caller,
		"coinIn", u(aCoin), "grinIn", u(aHub), "shares", u(minted))
	return minted
}

// lpPayout computes what `shares` of a position withdraw right now:
// pro-rata of CURRENT reserves (floor). Within the warm-up the fee growth
// since entry (√k/share above entry) stays in the pool for the other LPs;
// principal is never cut below its entry-value share.
func lpPayout(p *pool, pos *lpPos, shares uint64, now int64) (uint64, uint64) {
	outCoin := mulDiv(shares, p.rCoin, p.shares)
	outHub := mulDiv(shares, p.rHub, p.shares)
	if now-pos.depositTs < warmupSecs {
		rk := rootKPerShare(p)
		if rk > pos.entryRKPS {
			outCoin = mulDiv(outCoin, pos.entryRKPS, rk)
			outHub = mulDiv(outHub, pos.entryRKPS, rk)
		}
	}
	return outCoin, outHub
}

// RemoveLiquidity is instant and ALWAYS available: it works while the
// exchange or the pool is paused, before or after a ban, and needs no tool.
// Nobody but the position owner can call it for that position.
func RemoveLiquidity(cur realm, coin string, shares uint64, minCoin uint64, minGrin uint64, deadline int64) (uint64, uint64) {
	caller := exchangeCaller(cur)
	requireDeadline(deadline)
	p := getPool(coin)
	key := coin + ":" + caller
	if !lpPositions.Has(key) {
		panic("no liquidity position in " + coin)
	}
	pos := lpPositions.Get(key).(*lpPos)
	if shares == 0 || shares > pos.shares {
		panic("invalid shares")
	}
	outCoin, outHub := lpPayout(p, pos, shares, time.Now().Unix())
	if outCoin < minCoin || outHub < minGrin {
		panic("slippage: output below minimum")
	}
	p.rCoin = subChk(p.rCoin, outCoin)
	p.rHub = subChk(p.rHub, outHub)
	p.shares = subChk(p.shares, shares)
	pos.shares = subChk(pos.shares, shares)
	if pos.shares == 0 {
		lpPositions.Remove(key)
	}
	creditBal(caller, coin, outCoin)
	creditBal(caller, hubCoin, outHub)
	std.Emit("LiquidityRemoved", "coin", coin, "who", caller,
		"coinOut", u(outCoin), "grinOut", u(outHub), "shares", u(shares))
	return outCoin, outHub
}

// poolQuote returns (out, protoFee) for amountIn of the input side; no writes.
func poolQuote(p *pool, inIsHub bool, amountIn uint64) (uint64, uint64) {
	rIn, rOut := p.rCoin, p.rHub
	if inIsHub {
		rIn, rOut = p.rHub, p.rCoin
	}
	fee := mulDivUp(amountIn, poolFeeBps, 10000)
	proto := mulDiv(amountIn, protoFeeBps, 10000)
	if fee >= amountIn {
		return 0, 0
	}
	eff := amountIn - fee
	out := mulDiv(rOut, eff, addChk(rIn, eff)) // floor: pool's favor
	return out, proto
}

func poolOpenForSwaps(p *pool) bool {
	return !p.paused && p.rHub >= minOpenDepthGrin && p.rCoin > 0
}

// poolSwap executes one hop (coin↔grin) for `caller`, crediting nothing to
// the caller: it returns the output so routes can chain hops. The caller's
// input must already have been debited.
func poolSwap(p *pool, inIsHub bool, amountIn uint64) uint64 {
	if !poolOpenForSwaps(p) {
		panic("pool " + p.coin + " is not open for swaps (paused or under 2000 grin depth)")
	}
	out, proto := poolQuote(p, inIsHub, amountIn)
	if out == 0 {
		panic("swap too small")
	}
	kBefore := isqrt128(p.rCoin, p.rHub)
	inNet := subChk(amountIn, proto)
	if inIsHub {
		p.rHub = addChk(p.rHub, inNet)
		p.rCoin = subChk(p.rCoin, out)
		accrueProtocolFee(hubCoin, proto)
	} else {
		p.rCoin = addChk(p.rCoin, inNet)
		p.rHub = subChk(p.rHub, out)
		accrueProtocolFee(p.coin, proto)
	}
	if p.rCoin == 0 || p.rHub == 0 {
		panic("swap would empty the pool")
	}
	// Defense in depth: the invariant must hold after every swap.
	if isqrt128(p.rCoin, p.rHub) < kBefore {
		panic("invariant: k decreased")
	}
	return out
}

// SwapExactIn swaps amountIn of coinIn for at least minOut of coinOut through
// one pool (one side must be grin). For X→Y via grin use SwapRoute.
func SwapExactIn(cur realm, coinIn string, coinOut string, amountIn uint64, minOut uint64, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireAmount("amountIn", amountIn)
	requireCoin(coinIn)
	requireCoin(coinOut)
	var p *pool
	inIsHub := coinIn == hubCoin
	if inIsHub && coinOut != hubCoin {
		p = getPool(coinOut)
	} else if !inIsHub && coinOut == hubCoin {
		p = getPool(coinIn)
	} else {
		panic("one side must be grin (use SwapRoute for coin→coin)")
	}
	if !poolOpenForSwaps(p) {
		panic("pool " + p.coin + " is not open for swaps (paused or under 2000 grin depth)")
	}
	if q, _ := poolQuote(p, inIsHub, amountIn); q == 0 || q < minOut {
		panic("slippage: output below minimum")
	}
	requireBalance(caller, coinIn, amountIn)
	// ── all checks passed; writes start here ──
	debitBal(caller, coinIn, amountIn)
	out := poolSwap(p, inIsHub, amountIn)
	creditBal(caller, coinOut, out)
	std.Emit("Swap", "pool", p.coin, "who", caller, "in", coinIn, "out", coinOut,
		"amountIn", u(amountIn), "amountOut", u(out))
	return out
}

// ── views ────────────────────────────────────────────────────────────────────

func poolJSON(p *pool) string {
	return `{"coin":` + jsonStr(p.coin) + `,"rCoin":"` + u(p.rCoin) + `","rGrin":"` + u(p.rHub) +
		`","shares":"` + u(p.shares) + `","paused":` + strconv.FormatBool(p.paused) +
		`,"open":` + strconv.FormatBool(poolOpenForSwaps(p)) + `}`
}

func PoolInfo(coin string) string {
	if !pools.Has(coin) {
		return `{"coin":` + jsonStr(coin) + `,"exists":false}`
	}
	return poolJSON(getPool(coin))
}

// Pools lists pools in coin order (paginated, ≤ 50 per call).
func Pools(limit int, offset int) string {
	if limit <= 0 || limit > maxViewLimit {
		limit = maxViewLimit
	}
	if offset < 0 {
		offset = 0
	}
	out := "["
	n := 0
	pools.IterateByOffset(offset, limit, func(_ string, v any) bool {
		if n > 0 {
			out += ","
		}
		out += poolJSON(v.(*pool))
		n++
		return false
	})
	return out + "]"
}

// QuoteSwap quotes a single-pool swap; "0" if the pool can't take it.
func QuoteSwap(coinIn string, coinOut string, amountIn uint64) string {
	if amountIn == 0 || amountIn > maxAmount {
		return "0"
	}
	c, inIsHub := coinIn, false
	if coinIn == hubCoin {
		c, inIsHub = coinOut, true
	} else if coinOut != hubCoin {
		return "0"
	}
	if !pools.Has(c) {
		return "0"
	}
	p := getPool(c)
	if !poolOpenForSwaps(p) {
		return "0"
	}
	out, _ := poolQuote(p, inIsHub, amountIn)
	return u(out)
}

// LpPosition shows one position and what it would withdraw right now.
func LpPosition(coin string, addr string) string {
	key := coin + ":" + addr
	if !lpPositions.Has(key) || !pools.Has(coin) {
		return `{"coin":` + jsonStr(coin) + `,"shares":"0"}`
	}
	pos := lpPositions.Get(key).(*lpPos)
	p := getPool(coin)
	now := time.Now().Unix()
	oc, oh := lpPayout(p, pos, pos.shares, now)
	warm := pos.depositTs + warmupSecs - now
	if warm < 0 {
		warm = 0
	}
	return `{"coin":` + jsonStr(coin) + `,"shares":"` + u(pos.shares) + `","poolShares":"` + u(p.shares) +
		`","coinOut":"` + u(oc) + `","grinOut":"` + u(oh) + `","warmupLeft":` + strconv.FormatInt(warm, 10) + `}`
}

// LpPositions lists an address's positions (bounded: at most one per pool,
// paginated by pool order, ≤ 50 pools scanned per call).
func LpPositions(addr string, limit int, offset int) string {
	if limit <= 0 || limit > maxViewLimit {
		limit = maxViewLimit
	}
	if offset < 0 {
		offset = 0
	}
	out := "["
	n := 0
	pools.IterateByOffset(offset, limit, func(coin string, _ any) bool {
		if lpPositions.Has(coin + ":" + addr) {
			if n > 0 {
				out += ","
			}
			out += LpPosition(coin, addr)
			n++
		}
		return false
	})
	return out + "]"
}

package game29

// ── P2P exchange: router (book first while it beats the pool, rest via pools)

import (
	"std"
	"strconv"
	"time"
)

// poolPathOut quotes amountIn of coinIn → coinOut through the grin pools
// (one hop if either side is grin, else coinIn→grin→coinOut). ok=false if a
// needed pool is missing or not open. Read-only.
func poolPathOut(coinIn, coinOut string, amountIn uint64) (uint64, bool) {
	if amountIn == 0 || coinIn == coinOut {
		return 0, false
	}
	if coinIn == hubCoin || coinOut == hubCoin {
		c, inIsHub := coinIn, false
		if coinIn == hubCoin {
			c, inIsHub = coinOut, true
		}
		if !pools.Has(c) {
			return 0, false
		}
		p := getPool(c)
		if !poolOpenForSwaps(p) {
			return 0, false
		}
		out, _ := poolQuote(p, inIsHub, amountIn)
		return out, out > 0
	}
	mid, ok := poolPathOut(coinIn, hubCoin, amountIn)
	if !ok {
		return 0, false
	}
	return poolPathOut(hubCoin, coinOut, mid)
}

// routePlan splits amountIn between book fills (direct pair) and the pool
// path. A book fill is taken while its rate is at least the pool path's
// average rate for the whole remainder; everything else goes to the pools.
func routePlan(caller, coinIn, coinOut string, amountIn uint64, maxFills int, now int64) ([]fillStep, []*order, uint64, uint64, uint64) {
	steps, expired, _, _ := planFills(caller, coinIn, coinOut, amountIn, maxFills, now)
	var take []fillStep
	remaining := amountIn
	bookOut := uint64(0)
	for _, st := range steps {
		cost := addChk(st.x, mulDivUp(st.x, takerFeeBps, 10000))
		if cost > remaining {
			break
		}
		if pOut, ok := poolPathOut(coinIn, coinOut, remaining); ok {
			// book rate g/cost vs pool average rate pOut/remaining (128-bit compare)
			if mulLess(st.g, remaining, pOut, cost) {
				break
			}
		}
		take = append(take, st)
		remaining = subChk(remaining, cost)
		bookOut = addChk(bookOut, st.g)
	}
	poolOut := uint64(0)
	if remaining > 0 {
		if out, ok := poolPathOut(coinIn, coinOut, remaining); ok {
			poolOut = out
		} else {
			remaining = 0 // no pool path: only the book part executes
		}
	}
	return take, expired, remaining, bookOut, poolOut
}

// SwapRoute swaps up to amountIn of coinIn for at least minOut of coinOut,
// using the order book (direct pair) while it beats the pools and the grin
// pools for the rest. Coins not needed are never debited.
func SwapRoute(cur realm, coinIn string, coinOut string, amountIn uint64, minOut uint64, maxFills int, deadline int64) uint64 {
	caller := exchangeCaller(cur)
	requireMarketOpen(caller)
	requireDeadline(deadline)
	requireAmount("amountIn", amountIn)
	requireCoin(coinIn)
	requireCoin(coinOut)
	if coinIn == coinOut {
		panic("coinIn and coinOut must differ")
	}
	take, expired, poolIn, bookOut, poolOut := routePlan(caller, coinIn, coinOut, amountIn, maxFills, time.Now().Unix())
	planned := addChk(bookOut, poolOut)
	if planned == 0 || planned < minOut {
		panic("slippage: output below minimum")
	}
	need := poolIn
	for _, st := range take {
		need = addChk(need, addChk(st.x, mulDivUp(st.x, takerFeeBps, 10000)))
	}
	requireBalance(caller, coinIn, need)
	// ── all checks passed; writes start here ──
	for _, o := range expired {
		closeOrder(o, "expired")
	}
	out := executeFills(caller, coinIn, take)
	if poolIn > 0 {
		debitBal(caller, coinIn, poolIn)
		if coinIn == hubCoin {
			out = addChk(out, poolSwap(getPool(coinOut), true, poolIn))
		} else if coinOut == hubCoin {
			out = addChk(out, poolSwap(getPool(coinIn), false, poolIn))
		} else {
			mid := poolSwap(getPool(coinIn), false, poolIn)
			out = addChk(out, poolSwap(getPool(coinOut), true, mid))
		}
	}
	if out != planned {
		panic("invariant: route plan mismatch")
	}
	creditBal(caller, coinOut, out)
	std.Emit("SwapRouted", "who", caller, "in", coinIn, "out", coinOut, "amountIn", u(amountIn),
		"bookFills", strconv.Itoa(len(take)), "poolIn", u(poolIn), "amountOut", u(out))
	return out
}

// QuoteRoute previews SwapRoute: how much goes to the book vs the pools and
// the expected output (fees included).
func QuoteRoute(caller string, coinIn string, coinOut string, amountIn uint64, maxFills int) string {
	if amountIn == 0 || amountIn > maxAmount || coinIn == coinOut {
		return `{"out":"0"}`
	}
	if _, ok := coinRarity[coinIn]; !ok {
		return `{"out":"0"}`
	}
	if _, ok := coinRarity[coinOut]; !ok {
		return `{"out":"0"}`
	}
	take, _, poolIn, bookOut, poolOut := routePlan(caller, coinIn, coinOut, amountIn, maxFills, time.Now().Unix())
	bookIn := uint64(0)
	for _, st := range take {
		bookIn = addChk(bookIn, addChk(st.x, mulDivUp(st.x, takerFeeBps, 10000)))
	}
	return `{"bookIn":"` + u(bookIn) + `","bookOut":"` + u(bookOut) + `","bookFills":` + strconv.Itoa(len(take)) +
		`,"poolIn":"` + u(poolIn) + `","poolOut":"` + u(poolOut) + `","out":"` + u(addChk(bookOut, poolOut)) +
		`","unused":"` + u(amountIn-bookIn-poolIn) + `"}`
}

package game29

import (
	"std"
	"encoding/hex"
	"strconv"
	"strings"
	"time"
)

func init(cur realm) {
	// The deployer (tx signer of addpkg) becomes admin and default operator.
	admin = address(cur.Previous().Address())
	operator = admin
}

// ── Roles ────────────────────────────────────────────────────────────────────

func isAdmin(cur realm) bool {
	return admin != address("") && cur.Previous().Address() == admin
}

func requireAdmin(cur realm) {
	if !isAdmin(cur) {
		panic("unauthorized: admin only")
	}
}


// TransferAdmin hands the admin role to another address.
func TransferAdmin(cur realm, newAdmin string) {
	requireAdmin(cur)
	transferAdmin(newAdmin)
}

func transferAdmin(newAdmin string) {
	a := address(newAdmin)
	if !a.IsValid() {
		panic("invalid address")
	}
	admin = a
}

// UpdateConfig is kept for game27/28 API compatibility (= TransferAdmin).
func UpdateConfig(cur realm, newAdmin string) {
	requireAdmin(cur)
	transferAdmin(newAdmin)
}


// SetClaimSigner registers the ed25519 public key (64 hex chars) of the
// server's claim signer. Pass "" to disable all vouchered calls (kill switch).
func SetClaimSigner(cur realm, pubKeyHex string) {
	requireAdmin(cur)
	if pubKeyHex == "" {
		claimSignerPubKey = nil
		return
	}
	b, err := hex.DecodeString(pubKeyHex)
	if err != nil || len(b) != 32 {
		panic("claim signer must be a 32-byte ed25519 public key in hex")
	}
	claimSignerPubKey = b
}

func ClaimSigner() string { return hex.EncodeToString(claimSignerPubKey) }
func Admin() string       { return admin.String() }

func SetPaused(cur realm, p bool) {
	requireAdmin(cur)
	paused = p
}

func IsPaused() bool { return paused }

func requireNotPaused() {
	if paused {
		panic("game is paused")
	}
}

// ── Blacklist ─────────────────────────────────────────────────────────────────

// BanAddress bans a player address. durationSecs=0 means permanent.
func BanAddress(cur realm, targetAddr string, reason string, durationSecs int64) {
	requireAdmin(cur)
	if !address(targetAddr).IsValid() {
		panic("invalid address")
	}
	expiry := int64(0)
	if durationSecs > 0 {
		expiry = time.Now().Unix() + durationSecs
	}
	blacklist.Set(targetAddr, strings.ReplaceAll(reason, ":", " ")+":"+strconv.FormatInt(time.Now().Unix(), 10))
	banExpiries.Set(targetAddr, strconv.FormatInt(expiry, 10))
}

func UnbanAddress(cur realm, targetAddr string) {
	requireAdmin(cur)
	blacklist.Remove(targetAddr)
	banExpiries.Remove(targetAddr)
}

func BlacklistStatus(addr string) string {
	if !blacklist.Has(addr) {
		return `{"banned":false}`
	}
	entry := blacklist.Get(addr).(string)
	expiry, _ := strconv.ParseInt(banExpiries.Get(addr).(string), 10, 64)
	now := time.Now().Unix()
	if expiry > 0 && now >= expiry {
		return `{"banned":false}`
	}
	reason := strings.SplitN(entry, ":", 2)[0]
	if expiry == 0 {
		return `{"banned":true,"reason":` + jsonStr(reason) + `,"permanent":true}`
	}
	return `{"banned":true,"reason":` + jsonStr(reason) + `,"permanent":false,"remainingSecs":` + strconv.FormatInt(expiry-now, 10) + `}`
}

func isBlacklisted(addr string) bool {
	if !blacklist.Has(addr) {
		return false
	}
	expiry, _ := strconv.ParseInt(banExpiries.Get(addr).(string), 10, 64)
	if expiry == 0 {
		return true
	}
	return time.Now().Unix() < expiry
}

func requirePlayer(cur realm) string {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	if isBlacklisted(caller) {
		panic("address banned")
	}
	return caller
}

// ── Veins ────────────────────────────────────────────────────────────────────

func veinMax(coinId string) uint64 {
	// FIX 2B: skip AVL read when no overrides have ever been set.
	if veinOverrideActive && veinMaxOverride.Has(coinId) {
		v, _ := strconv.ParseUint(veinMaxOverride.Get(coinId).(string), 10, 64)
		return v
	}
	r, ok := coinRarity[coinId]
	if !ok {
		return 0
	}
	if v, ok := veinCoinDefault[coinId]; ok {
		return v
	}
	return veinDefaultMax[r]
}

func veinMintedOf(coinId string) uint64 {
	if !veinMinted.Has(coinId) {
		return 0
	}
	v, _ := strconv.ParseUint(veinMinted.Get(coinId).(string), 10, 64)
	return v
}

// takeFromVein returns how much of amt can still be minted for coinId and
// records it as minted.
func takeFromVein(coinId string, amt uint64) uint64 {
	mx := veinMax(coinId)
	mi := veinMintedOf(coinId)
	if mi >= mx {
		return 0
	}
	if amt > mx-mi {
		amt = mx - mi
	}
	veinMinted.Set(coinId, strconv.FormatUint(mi+amt, 10))
	if half := mx / 2; mi < half && mi+amt >= half {
		std.Emit("VeinHalfMinted", "coin", coinId,
			"minted", strconv.FormatUint(mi+amt, 10), "max", strconv.FormatUint(mx, 10))
	}
	if mi+amt == mx {
		std.Emit("VeinExhausted", "coin", coinId, "max", strconv.FormatUint(mx, 10))
	}
	return amt
}

// SetVeinMax overrides a coin's vein size. It can't go below what was minted.
func SetVeinMax(cur realm, coinId string, maxSupply string) {
	requireAdmin(cur)
	setVeinMax(coinId, maxSupply)
}

func setVeinMax(coinId string, maxSupply string) {
	if _, ok := coinRarity[coinId]; !ok {
		panic("unknown coin id: " + coinId)
	}
	mx, err := strconv.ParseUint(maxSupply, 10, 64)
	if err != nil {
		panic("invalid max supply")
	}
	if mx < veinMintedOf(coinId) {
		panic("vein max below already-minted supply")
	}
	veinMaxOverride.Set(coinId, strconv.FormatUint(mx, 10))
	veinOverrideActive = true
}

// RegisterVein is the game28 name for SetVeinMax.
func RegisterVein(cur realm, coinId string, maxSupply string) {
	requireAdmin(cur)
	setVeinMax(coinId, maxSupply)
}

func VeinSupply(coinId string) string {
	if _, ok := coinRarity[coinId]; !ok {
		return `{"remaining":"0","max":"0"}`
	}
	mx := veinMax(coinId)
	mi := veinMintedOf(coinId)
	rem := uint64(0)
	if mx > mi {
		rem = mx - mi
	}
	return `{"remaining":"` + strconv.FormatUint(rem, 10) + `","max":"` + strconv.FormatUint(mx, 10) + `","minted":"` + strconv.FormatUint(mi, 10) + `","halfMinted":` + strconv.FormatBool(mx > 0 && mi >= mx/2) + `,"exhausted":` + strconv.FormatBool(mx > 0 && mi >= mx) + `}`
}

// ── Gnome Pass (paid) ────────────────────────────────────────────────────────

// SetPassPrice sets the ugnot price per 30-day period.
func SetPassPrice(cur realm, ugnotPer30Days int64) {
	requireAdmin(cur)
	if ugnotPer30Days <= 0 {
		panic("price must be > 0")
	}
	passPriceUgnot = ugnotPer30Days
}

func PassPrice() int64 { return passPriceUgnot }

// ActivateGnomePass buys durationDays (30..360, multiple of 30) of Gnome Pass.
// The tx must attach exactly passPrice × durationDays/30 ugnot (MsgCall send).
func ActivateGnomePass(cur realm, durationDays int64) {
	caller := requirePlayer(cur)
	// Payment verification must only trust the origin envelope when the
	// caller is the signer itself (no intermediate realm can consume it).
	if cur.Previous().PkgPath() != "" {
		panic("Gnome Pass must be bought directly by the player")
	}
	if durationDays <= 0 || durationDays%30 != 0 || durationDays > 360 {
		panic("durationDays must be 30, 60, ... 360")
	}
	periods := durationDays / 30
	required := passPriceUgnot * periods
	sent := std.GetOrigSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != required {
		panic("Gnome Pass costs " + strconv.FormatInt(required, 10) + "ugnot for " + strconv.FormatInt(durationDays, 10) + " days — attach exactly that amount")
	}
	passRevenueUgnot += required

	now := time.Now().Unix()
	base := now
	if gnomePasses.Has(caller) {
		existing, _ := strconv.ParseInt(gnomePasses.Get(caller).(string), 10, 64)
		if existing > now {
			base = existing
		}
	}
	gnomePasses.Set(caller, strconv.FormatInt(base+durationDays*86400, 10))
}

func GnomePassExpiry(addr string) int64 {
	if !gnomePasses.Has(addr) {
		return 0
	}
	expiry, _ := strconv.ParseInt(gnomePasses.Get(addr).(string), 10, 64)
	return expiry
}

func HasActivePass(addr string) bool { return GnomePassExpiry(addr) > time.Now().Unix() }

func GnomePassCount() int {
	count := 0
	now := time.Now().Unix()
	gnomePasses.Iterate("", "", func(_ string, val any) bool {
		e, _ := strconv.ParseInt(val.(string), 10, 64)
		if e > now {
			count++
		}
		return false
	})
	return count
}

func PassRevenue() int64 { return passRevenueUgnot }

// TreasuryBalance returns the ugnot held by this realm (pass revenue not yet withdrawn).
func TreasuryBalance() int64 {
	realmAddr := std.CurrentRealm().Addr()
	coins := std.GetBanker(std.BankerTypeReadonly).GetCoins(realmAddr)
	for _, c := range coins {
		if c.Denom == "ugnot" {
			return c.Amount
		}
	}
	return 0
}

// WithdrawFunds sends GNOT the admin is OWED — Gnome Pass revenue not yet
// withdrawn — to `to`. It can never touch other ugnot the realm holds
// (donations, anything a future feature would hold for players).
func WithdrawFunds(cur realm, to string, amountUgnot int64) {
	requireAdmin(cur)
	dst := std.Address(to)
	if !dst.IsValid() {
		panic("invalid address")
	}
	if amountUgnot <= 0 {
		panic("amount must be > 0")
	}
	if amountUgnot > passRevenueUgnot-adminGnotWithdrawn {
		panic("can only withdraw unwithdrawn pass revenue: " + strconv.FormatInt(passRevenueUgnot-adminGnotWithdrawn, 10) + "ugnot")
	}
	adminGnotWithdrawn += amountUgnot
	b := std.GetBanker(std.BankerTypeRealmSend)
	b.SendCoins(std.CurrentRealm().Addr(), dst, std.Coins{std.NewCoin("ugnot", amountUgnot)})
	std.Emit("FundsWithdrawn", "to", to, "ugnot", strconv.FormatInt(amountUgnot, 10))
}

// WithdrawableFunds = pass revenue the admin may still withdraw (ugnot).
func WithdrawableFunds() int64 { return passRevenueUgnot - adminGnotWithdrawn }

// ── Migration (game27 / game28 → game29) ────────────────────────────────────
//
// MigrateBatch(batchId, kind, rowsJson) imports one batch. rowsJson is a JSON
// array of string arrays. Kinds and row shapes:
//   balance  [addr, coinId, amount]       → balances (SET, not add)
//   lifetime [addr, coinId, amount]       → lifetimeMined (SET) + miners total
//   tools    [addr, "t1,t2,..."]          → ownedTools (SET, unknown ids dropped)
//   toollife [addr, toolId, life]         → toolLife (SET, clamped to max)
//   skill    [addr, skillId, rank]        → skillRanks (SET, clamped to max)
//   medal    [addr, achievementId]        → achievements (allowlisted ids only)
//   pass     [addr, expiryUnix]           → gnomePasses (SET)
//   guild    [guildId, name, leader, "m1,m2,..."] → guilds + members
//   ban      [addr, reason, expiryUnix]   → blacklist (expiry 0 = permanent)
// A batchId that was already applied is skipped, and every write is a SET, so
// re-running a whole migration is a no-op. FinalizeMigration locks it forever.
func MigrateBatch(cur realm, batchId string, kind string, rowsJson string) int {
	requireAdmin(cur)
	if migrationFinalized {
		panic("migration is finalized")
	}
	if batchId == "" {
		panic("batchId required")
	}
	if migrationBatches.Has(batchId) {
		return 0
	}
	rows := parseStringRows(rowsJson)
	n := 0
	for _, r := range rows {
		if migrateRow(kind, r) {
			n++
		}
	}
	migrationBatches.Set(batchId, kind+":"+strconv.Itoa(n))
	return n
}

func FinalizeMigration(cur realm) {
	requireAdmin(cur)
	migrationFinalized = true
}

func MigrationStatus() string {
	return `{"finalized":` + strconv.FormatBool(migrationFinalized) + `,"batches":` + strconv.Itoa(migrationBatches.Size()) + `}`
}

func MigrationBatch(batchId string) string {
	if !migrationBatches.Has(batchId) {
		return ""
	}
	return migrationBatches.Get(batchId).(string)
}

func validAddr(s string) bool { return address(s).IsValid() }

func migrateRow(kind string, r []string) bool {
	switch kind {
	case "balance", "lifetime":
		if len(r) != 3 || !validAddr(r[0]) {
			return false
		}
		if _, ok := coinRarity[r[1]]; !ok {
			return false
		}
		amt, err := strconv.ParseUint(r[2], 10, 64)
		if err != nil {
			return false
		}
		key := r[0] + ":" + r[1]
		if kind == "balance" {
			old := getU(&balances, key)
			// Imported balances count against the vein (delta on re-run).
			if amt > old {
				mi := veinMintedOf(r[1])
				veinMinted.Set(r[1], strconv.FormatUint(mi+(amt-old), 10))
			}
			setU(&balances, key, amt)
		} else {
			old := getU(&lifetimeMined, key)
			setU(&lifetimeMined, key, amt)
			tot := getU(&miners, r[0])
			if tot >= old {
				tot -= old
			} else {
				tot = 0
			}
			setU(&miners, r[0], tot+amt)
		}
		return true
	case "tools":
		if len(r) != 2 || !validAddr(r[0]) {
			return false
		}
		var keep []string
		seen := map[string]bool{}
		for _, t := range strings.Split(r[1], ",") {
			t = strings.TrimSpace(t)
			if t == "" || t == "hands" || seen[t] {
				continue
			}
			if _, ok := toolCosts[t]; !ok {
				continue
			}
			seen[t] = true
			keep = append(keep, t)
		}
		if len(keep) == 0 {
			ownedTools.Remove(r[0])
		} else {
			ownedTools.Set(r[0], strings.Join(keep, ","))
		}
		return true
	case "toollife":
		if len(r) != 3 || !validAddr(r[0]) {
			return false
		}
		mx, ok := toolMaxLife[r[1]]
		if !ok || mx == 0 {
			return false
		}
		life, err := strconv.ParseUint(r[2], 10, 64)
		if err != nil {
			return false
		}
		if em := effectiveMaxLife(r[0], r[1]); life > em {
			life = em
		}
		setU(&toolLife, r[0]+":"+r[1], life)
		return true
	case "skill":
		if len(r) != 3 || !validAddr(r[0]) {
			return false
		}
		mx, ok := skillMaxRanks[r[1]]
		if !ok {
			return false
		}
		rank, err := strconv.ParseUint(r[2], 10, 64)
		if err != nil {
			return false
		}
		if rank > mx {
			rank = mx
		}
		setU(&skillRanks, r[0]+":"+r[1], rank)
		return true
	case "medal":
		if len(r) != 2 || !validAddr(r[0]) || !isValidAchievementId(r[1]) {
			return false
		}
		achievements.Set(r[0]+":"+r[1], "1")
		return true
	case "pass":
		if len(r) != 2 || !validAddr(r[0]) {
			return false
		}
		e, err := strconv.ParseInt(r[1], 10, 64)
		if err != nil || e <= 0 {
			return false
		}
		gnomePasses.Set(r[0], strconv.FormatInt(e, 10))
		return true
	case "guild":
		if len(r) != 4 || r[0] == "" || !validAddr(r[2]) {
			return false
		}
		name := sanitizeName(r[1])
		if len(name) < 3 {
			return false
		}
		members := []string{}
		for _, m := range strings.Split(r[3], ",") {
			m = strings.TrimSpace(m)
			if validAddr(m) && len(members) < maxGuildMembers {
				members = append(members, m)
			}
		}
		if len(members) == 0 {
			return false
		}
		// Drop stale membership rows of this guild, then write fresh ones.
		var stale []string
		guildMembers.Iterate(r[0]+":", r[0]+";", func(k string, _ any) bool {
			stale = append(stale, k)
			return false
		})
		for _, k := range stale {
			guildMembers.Remove(k)
		}
		for _, m := range members {
			guildMembers.Set(r[0]+":"+m, "1")
			playerGuild.Set(m, r[0])
		}
		guildMetas[r[0]] = guildMeta{name: name, leader: r[2], createdAt: time.Now().Unix()}
		rewriteGuild(r[0])
		return true
	case "ban":
		if len(r) != 3 || !validAddr(r[0]) {
			return false
		}
		e, err := strconv.ParseInt(r[2], 10, 64)
		if err != nil || e < 0 {
			return false
		}
		blacklist.Set(r[0], strings.ReplaceAll(r[1], ":", " ")+":"+strconv.FormatInt(time.Now().Unix(), 10))
		banExpiries.Set(r[0], strconv.FormatInt(e, 10))
		return true
	}
	panic("unknown migration kind: " + kind)
}

package game29

import (
	"std"
	"crypto/sha256"
	"encoding/hex"
	"math/bits"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

// ── Casino: two-sided commit–reveal, settled and paid on chain ──────────────
//
// One round = one bet by one player:
//   1. CommitCasinoSeed(roundId, player, sha256(s))        operator
//        s is 32 fresh random bytes for this round, kept by the server.
//   2. PlaceCasinoBet(roundId, game, coin, amt, choice, sha256(c))   the player
//        c is the player's secret (made and kept by the browser). The stake is
//        debited and the bet's largest possible net win is reserved in the pool.
//   3. RevealCasinoSeed(roundId, s)                        operator
//        s must hash to the commit. The operator still doesn't know c, so it
//        doesn't know the result when it reveals.
//   4. RevealCasinoSecret(roundId, c)                      anyone (a preimage)
//        c must hash to the bet's hash; the realm rolls and settles the bet.
// Timeouts (nobody can profit from withholding):
//   - s not revealed 30 min after the bet → RefundCasinoBet (full stake back).
//   - s revealed but c not revealed within 24 h → ForfeitCasinoBet (anyone):
//     the bet settles as a loss; only the player could have known the result.
//   No refund once s is revealed.
//
// Results (the only rules; the client re-derives and shows them):
//   roll = uint32(sha256(s:c:roundId:game)[0:4]) % 100
//   coin_flip:    0..48 heads, 51..99 tails, 49/50 edge (house)      win pays 2×
//   higher_lower: 51..99 higher, 0..48 lower, 49/50 house              win pays 2×
//   rps:          0..32 player wins (2×), 33..64 push (stake back), 65..99 house
//                 wins; the house move shown is derived from that. RTP 98%.
//   slots:        reels/lines/scatters/Hold & Spin from the stream in game_slots.gno;
//                 free spins and MAJOR/GRAND jackpots in game_casino_bonus.gno.
//
// Pool safety (fixed in code):
//   coin_flip / wheel / rps bet ≤ 0.5% of the free pool; slots bet ≤ 0.004%
//   (its 500× max win then reserves ≤ 2% of the pool); every open bet reserves
//   its largest net win; open reservations ≤ 20% of the pool; net paid today +
//   reservations ≤ 10% of the pool at 00:00 UTC; opens at ≥ 20,000 grin-eq and
//   ≥ 200 units. Coins only move between players and the pool: nothing is
//   minted, and the admin can't withdraw the pool.

var (
	casinoBets     avl.Tree // roundId+":"+addr → *casinoBet
	casinoReserved avl.Tree // coin → largest net payouts of unsettled bets (string)
	casinoDay      avl.Tree // coin → "day:snapshot:paid:received" (UTC day)
)

const (
	casinoWinRange         = uint64(49)       // winning rolls per pick (of 100) for flip/wheel
	rpsWinBelow            = uint64(33)       // rps: roll < 33 player wins
	rpsPushBelow           = uint64(65)       // rps: 33..64 push
	casinoBetWindowSec     = int64(3600)      // a committed round takes its bet within 1 h
	casinoSeedTimeoutSec   = int64(1800)      // refunds open 30 min after the bet if s is never revealed
	casinoSecretTimeoutSec = int64(86400)     // the bet forfeits 24 h after s if c is never revealed
	casinoMaxBetBps        = uint64(50)       // flip / wheel / rps bet ≤ 0.5% of the free pool
	slotsMaxBetPPM         = uint64(40)       // slots bet ≤ 0.004% of the free pool
	casinoOpenBps          = uint64(2000)     // open reservations on a coin ≤ 20% of the pool
	casinoDayBps           = uint64(1000)     // daily net payout ≤ 10% of the day's snapshot
	casinoMinPoolMilli     = uint64(20000000) // ≥ 20,000 grin-equivalent …
	casinoMinPoolUnits     = uint64(200)      // … and ≥ 200 units of the coin
	casinoMaxAmount        = uint64(1000000000)
)

// Reference value per unit by rarity, in milli-grin (same table as the
// exchange plan): only used for the pool's opening threshold.
var casinoRefMilli = [7]uint64{1000, 3200, 11000, 40000, 160000, 720000, 3600000}

type casinoRound struct {
	player      string
	seedHash    string
	serverSeed  string
	status      string // committed | bet | seeded | settled | refunded | closed
	committedAt int64
	betAt       int64
	seededAt    int64
	bets        int
}

type casinoBet struct {
	addr, game, coin, choice string
	clientHash, clientSecret string
	amount, exposure         uint64
	settled, won, refunded   bool
	forfeited                bool
	roll, payout             uint64
	outcome                  string
	// slots only
	grid       string
	lineMult   uint64
	lines      int
	scatters   int
	freeSpin   bool   // a free spin from a grant (no stake)
	capped     bool   // the round's win hit the 500× cap
	fsGranted  uint64 // free spins this spin granted
	hsTiles    string // Hold & Spin tiles ("." separated, 0 = empty)
	hsRespins  int
	hsMult     uint64 // Hold & Spin win in bets (MINI/MINOR included)
	jackpots   string // "major", "grand", "major+grand" or ""
	jackpotWin uint64 // paid from the jackpot pools (outside the cap)
}

// ── roles ────────────────────────────────────────────────────────────────────

// isOperator: the casino operator key commits and reveals server seeds. Once an
// operator is set, only that key can; the admin (treasury) key only stands in
// while no operator has been named yet (bootstrap and tests).
func isOperator(cur realm) bool {
	c := cur.Previous().Address()
	if operator != address("") {
		return c == operator
	}
	return admin != address("") && c == admin
}

// SetOperator lets the admin name the server account that commits and
// reveals casino seeds. It must be its own key, never the admin/treasury key.
// The operator can't move anyone's coins.
func SetOperator(cur realm, addr string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	a := address(addr)
	if !a.IsValid() {
		panic("invalid address")
	}
	if a == admin {
		panic("the casino operator must be a separate key, not the admin/treasury key")
	}
	operator = a
	std.Emit("CasinoOperatorSet", "operator", addr)
}

func Operator() string { return operator.String() }

// ── casino accounting (monitoring) ──────────────────────────────────────────
//
// Per coin: pool + MAJOR + GRAND == seeded + staked − paid, always. Per coin and
// game: rounds, staked, paid (free spins and jackpots count as slots pay), so
// realized RTP = paid / staked. Updated on every settlement; read by CasinoStats.

var casinoStats avl.Tree // coin:field or coin:game:field → uint (string)

func casStat(coin, game, field string, add uint64) {
	k := coin + ":" + field
	if game != "" {
		k = coin + ":" + game + ":" + field
	}
	casSet(&casinoStats, k, casAdd(casGet(&casinoStats, k), add))
}

func casRecord(coin, game string, staked, paid uint64) {
	casStat(coin, game, "rounds", 1)
	casStat(coin, game, "staked", staked)
	casStat(coin, game, "paid", paid)
	casStat(coin, "", "staked", staked)
	casStat(coin, "", "paid", paid)
}

// CasinoStats reports a coin's accounting: pool, reserved, jackpots, seeded,
// staked, paid, the conservation check and per-game rounds/staked/paid.
func CasinoStats(coinId string) string {
	pool := casGet(&casinoPool, coinId)
	major := casGet(&casinoJackpot, jpKey(coinId, "major"))
	grand := casGet(&casinoJackpot, jpKey(coinId, "grand"))
	seeded := casGet(&casinoStats, coinId+":seeded")
	staked := casGet(&casinoStats, coinId+":staked")
	paid := casGet(&casinoStats, coinId+":paid")
	fees := casGet(&casinoStats, coinId+":fees") // exchange protocol-fee inflow
	ok := pool+major+grand+paid == seeded+staked+fees
	out := `{"coin":"` + coinId + `","pool":"` + casU(pool) + `","reserved":"` + casU(casGet(&casinoReserved, coinId)) +
		`","major":"` + casU(major) + `","grand":"` + casU(grand) + `","seeded":"` + casU(seeded) +
		`","staked":"` + casU(staked) + `","paid":"` + casU(paid) + `","fees":"` + casU(fees) + `","conserved":` + strconv.FormatBool(ok) +
		`,"freeSpinsOpen":` + strconv.Itoa(casinoGrants.Size()) + `,"games":{`
	for i, g := range []string{"coin_flip", "higher_lower", "rps", "slots"} {
		if i > 0 {
			out += ","
		}
		out += `"` + g + `":{"rounds":` + casU(casGet(&casinoStats, coinId+":"+g+":rounds")) +
			`,"staked":"` + casU(casGet(&casinoStats, coinId+":"+g+":staked")) +
			`","paid":"` + casU(casGet(&casinoStats, coinId+":"+g+":paid")) + `"}`
	}
	return out + `}}`
}

// ── uint helpers (balances and pool values are decimal strings) ─────────────

func casGet(t *avl.Tree, key string) uint64 {
	if !t.Has(key) {
		return 0
	}
	v, _ := strconv.ParseUint(t.Get(key).(string), 10, 64)
	return v
}

func casSet(t *avl.Tree, key string, v uint64) { t.Set(key, strconv.FormatUint(v, 10)) }

func casAdd(a, b uint64) uint64 {
	s, carry := bits.Add64(a, b, 0)
	if carry != 0 {
		panic("math overflow")
	}
	return s
}

func casSub(a, b uint64) uint64 {
	if b > a {
		panic("math underflow")
	}
	return a - b
}

// casMulDiv = floor(a*b/c) with a 128-bit product.
func casMulDiv(a, b, c uint64) uint64 {
	hi, lo := bits.Mul64(a, b)
	if hi >= c {
		panic("math overflow")
	}
	q, _ := bits.Div64(hi, lo, c)
	return q
}

func casMul(a, b uint64) uint64 {
	hi, lo := bits.Mul64(a, b)
	if hi != 0 {
		panic("math overflow")
	}
	return lo
}

func casU(n uint64) string { return strconv.FormatUint(n, 10) }

func casBalOf(addr, coin string) uint64 { return casGet(&balances, addr+":"+coin) }

func casCredit(addr, coin string, amt uint64) {
	if amt > 0 {
		casSet(&balances, addr+":"+coin, casAdd(casBalOf(addr, coin), amt))
	}
}

func casDebit(addr, coin string, amt uint64) {
	have := casBalOf(addr, coin)
	if have < amt {
		panic("insufficient balance: need " + casU(amt) + " " + coin + ", have " + casU(have))
	}
	casSet(&balances, addr+":"+coin, have-amt)
}

func casGrinValueMilli(coin string, amt uint64) uint64 {
	r, ok := coinRarity[coin]
	if !ok || r < 0 || r > 6 {
		return 0
	}
	hi, lo := bits.Mul64(amt, casinoRefMilli[r])
	if hi != 0 {
		return ^uint64(0)
	}
	return lo
}

func casIsHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// casSafe: a short [A-Za-z0-9_.-] token (no quotes, so it is JSON-safe).
func casSafe(s string, maxLen int) bool {
	if s == "" || len(s) > maxLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '-' || c == '_' || c == '.') {
			return false
		}
	}
	return true
}

func sha256Hex(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

// ── outcome rules (the only ones; the client just re-derives them) ──────────

// CasinoRoll is the on-chain roll: uint32(sha256(s:c:roundId:game)[0:4]) % 100.
func CasinoRoll(serverSeed, clientSecret, roundId, game string) uint64 {
	h := sha256.Sum256([]byte(serverSeed + ":" + clientSecret + ":" + roundId + ":" + game))
	v := uint64(h[0])<<24 | uint64(h[1])<<16 | uint64(h[2])<<8 | uint64(h[3])
	return v % 100
}

// CasinoOutcome maps a roll to what landed. For rps the outcome is
// "win" | "push" | "lose" (see rpsHouseMove for the move shown).
func CasinoOutcome(game string, roll uint64) string {
	switch game {
	case "coin_flip":
		if roll < casinoWinRange {
			return "heads"
		}
		if roll >= 100-casinoWinRange {
			return "tails"
		}
		return "edge"
	case "higher_lower":
		if roll >= 100-casinoWinRange {
			return "higher"
		}
		if roll < casinoWinRange {
			return "lower"
		}
		return "house"
	case "rps":
		if roll < rpsWinBelow {
			return "win"
		}
		if roll < rpsPushBelow {
			return "push"
		}
		return "lose"
	}
	return ""
}

// rpsHouseMove: the house move that produces the outcome against the player's move.
func rpsHouseMove(choice, outcome string) string {
	beats := map[string]string{"rock": "scissors", "paper": "rock", "scissors": "paper"} // key beats value
	switch outcome {
	case "win":
		return beats[choice]
	case "push":
		return choice
	}
	for k, v := range beats {
		if v == choice {
			return k
		}
	}
	return ""
}

func validCasinoChoice(game, choice string) bool {
	switch game {
	case "coin_flip":
		return choice == "heads" || choice == "tails"
	case "higher_lower":
		return choice == "higher" || choice == "lower"
	case "rps":
		return choice == "rock" || choice == "paper" || choice == "scissors"
	case "slots":
		return casSafe(choice, 32)
	}
	return false
}

// casinoExposure: the largest net amount a bet can take from the pool.
func casinoExposure(game string, amt uint64) uint64 {
	if game == "slots" {
		return casMul(amt, slotsMaxWinMult-1)
	}
	return amt // flip / wheel / rps win pays 2× = net +amt
}

// ── pool ────────────────────────────────────────────────────────────────────

func casDayNow() int64 { return time.Now().Unix() / 86400 }

func casinoDayState(coin string) (int64, uint64, uint64, uint64) {
	day := casDayNow()
	if casinoDay.Has(coin) {
		f := strings.Split(casinoDay.Get(coin).(string), ":")
		d, _ := strconv.ParseInt(f[0], 10, 64)
		if d == day && len(f) == 4 {
			snap, _ := strconv.ParseUint(f[1], 10, 64)
			paid, _ := strconv.ParseUint(f[2], 10, 64)
			recv, _ := strconv.ParseUint(f[3], 10, 64)
			return day, snap, paid, recv
		}
	}
	return day, casGet(&casinoPool, coin), 0, 0 // first touch of the day: snapshot the pool
}

func setCasinoDay(coin string, day int64, snap, paid, recv uint64) {
	casinoDay.Set(coin, strconv.FormatInt(day, 10)+":"+casU(snap)+":"+casU(paid)+":"+casU(recv))
}

func casinoIsOpen(coin string, pool uint64) bool {
	return pool >= casinoMinPoolUnits && casGrinValueMilli(coin, pool) >= casinoMinPoolMilli
}

func casinoMaxBet(game string, free uint64) uint64 {
	if game == "slots" {
		m := casMulDiv(free, slotsMaxBetPPM, 1000000)
		return m - m%slotsBetStep
	}
	return casMulDiv(free, casinoMaxBetBps, 10000)
}

// casinoCheckBet panics unless the pool can pay the bet's largest win in full (read-only).
func casinoCheckBet(coin, game string, amt uint64) {
	pool := casGet(&casinoPool, coin)
	reserved := casGet(&casinoReserved, coin)
	if !casinoIsOpen(coin, pool) {
		panic("casino closed for " + coin + ": the pool needs at least 20,000 grin-equivalent and 200 " + coin)
	}
	if game == "slots" && (amt < slotsBetStep || amt%slotsBetStep != 0) {
		panic("slots bet must be a multiple of 25")
	}
	free := casSub(pool, reserved)
	maxBet := casinoMaxBet(game, free)
	if amt > maxBet {
		if game == "slots" {
			panic("bet too large: slots max is 0.004 percent of the free casino pool (" + casU(maxBet) + " " + coin + ")")
		}
		panic("bet too large: max is 0.5 percent of the free casino pool (" + casU(maxBet) + " " + coin + ")")
	}
	exp := casinoExposure(game, amt)
	if casAdd(reserved, exp) > casMulDiv(pool, casinoOpenBps, 10000) {
		panic("casino busy: open bets on " + coin + " would exceed 20 percent of the pool")
	}
	_, snap, paid, recv := casinoDayState(coin)
	net := uint64(0)
	if paid > recv {
		net = paid - recv
	}
	if casAdd(casAdd(net, reserved), exp) > casMulDiv(snap, casinoDayBps, 10000) {
		panic("casino daily payout limit reached for " + coin)
	}
}

func casinoReserve(coin string, exp uint64) {
	casSet(&casinoReserved, coin, casAdd(casGet(&casinoReserved, coin), exp))
	day, snap, paid, recv := casinoDayState(coin)
	setCasinoDay(coin, day, snap, paid, recv)
}

// casinoSettle releases the reservation and moves coins: the player receives
// `payout` (0 ≤ payout ≤ stake + exposure) and the pool keeps the rest of the
// stake or pays the difference. Returns payout.
func casinoSettle(addr, coin string, amt, exposure, payout uint64) uint64 {
	if payout > casAdd(amt, exposure) {
		panic("payout above the reservation")
	}
	casSet(&casinoReserved, coin, casSub(casGet(&casinoReserved, coin), exposure))
	day, snap, paid, recv := casinoDayState(coin)
	pool := casGet(&casinoPool, coin)
	if payout >= amt {
		win := payout - amt
		casSet(&casinoPool, coin, casSub(pool, win))
		setCasinoDay(coin, day, snap, casAdd(paid, win), recv)
	} else {
		keep := amt - payout
		casSet(&casinoPool, coin, casAdd(pool, keep))
		setCasinoDay(coin, day, snap, paid, casAdd(recv, keep))
	}
	casCredit(addr, coin, payout)
	return payout
}

// SeedCasinoPool moves the ADMIN'S OWN on-chain coins into a casino pool.
// Only ever the admin's own balance; nobody can withdraw a pool back.
func SeedCasinoPool(cur realm, coinId string, amount string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	if _, ok := coinRarity[coinId]; !ok {
		panic("unknown coin id: " + coinId)
	}
	amt, err := strconv.ParseUint(amount, 10, 64)
	if err != nil || amt == 0 || amt > casinoMaxAmount {
		panic("invalid amount")
	}
	from := admin.String()
	casDebit(from, coinId, amt)
	casSet(&casinoPool, coinId, casAdd(casGet(&casinoPool, coinId), amt))
	casStat(coinId, "", "seeded", amt)
	std.Emit("CasinoPoolSeeded", "coin", coinId, "from", from, "amount", amount)
}

// CasinoPool reports a coin's pool, reservation, max bets and daily counters.
func CasinoPool(coinId string) string {
	pool := casGet(&casinoPool, coinId)
	reserved := casGet(&casinoReserved, coinId)
	_, snap, paid, recv := casinoDayState(coinId)
	free := uint64(0)
	if pool > reserved {
		free = pool - reserved
	}
	return `{"coin":"` + coinId + `","pool":"` + casU(pool) + `","reserved":"` + casU(reserved) +
		`","maxBet":"` + casU(casinoMaxBet("coin_flip", free)) + `","slotsMaxBet":"` + casU(casinoMaxBet("slots", free)) +
		`","open":` + strconv.FormatBool(casinoIsOpen(coinId, pool)) +
		`,"daySnapshot":"` + casU(snap) + `","paidToday":"` + casU(paid) + `","receivedToday":"` + casU(recv) + `"}`
}

package game29

import (
	"std"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
)

// ── Slots bonus features, all settled by the realm ──────────────────────────
//
// Free spins: 3/4/5 scatters on a paid spin grant 10/12/15 free spins at that
// spin's bet. The grant is a realm record (one open grant per player). The
// triggering spin keeps its 500× reservation for the whole feature, minus what
// it already paid, so every free spin can always be paid in full. A free spin is
// its own two-sided round (PlaceCasinoFreeSpin takes no stake); its wins are
// doubled, it pays from that reservation, scatters don't retrigger and vaults
// don't start Hold & Spin. The grant never expires for the player.
//
// Hold & Spin: 3+ vaults on a paid spin. Resolved inside that spin's settlement
// from the same seed stream (game_slots.gno). Coin tiles pay 1/2/3/5× the bet,
// MINI 20×, MINOR 75× (all under the 500× cap). The first MAJOR / GRAND tile
// pays that jackpot pool (extra ones pay as MINOR); a full board (20 tiles) also
// awards GRAND.
//
// MAJOR / GRAND jackpots: real pools per coin, fed with 1.0% / 0.5% of every
// paid slots stake (fractions carried exactly). A hit pays
// pool × min(1, bet / refBet); the rest stays. A pool can never pay more than
// it holds. After a hit the pool is topped back up to its reset seed from the
// house pool, only while the free house pool is ≥ 20× that top-up. The admin
// can add its own coins to a jackpot but nobody can withdraw one.

var (
	casinoGrants  avl.Tree // addr → *freeSpinGrant
	casinoJackpot avl.Tree // coin:tier → pool (string)
	casinoJpDust  avl.Tree // coin:tier → contribution remainder in bet×bps units (string)
	casinoJpSeed  avl.Tree // coin:tier → reset seed (string)
	casinoJpRef   avl.Tree // coin → reference bet (string)
)

const (
	freeSpinMult        = uint64(2)
	jpMajorBps          = uint64(100) // 1.0% of each paid slots stake
	jpGrandBps          = uint64(50)  // 0.5%
	jpDefaultRefBet     = uint64(100)
	jpResetFreeMultiple = uint64(20)
	hsMiniMult          = uint64(20)
	hsMinorMult         = uint64(75)
)

type freeSpinGrant struct {
	addr, coin string
	bet        uint64
	left       uint64
	total      uint64
	capLeft    uint64 // still reserved in casinoReserved for this feature
	won        uint64
	inRound    string
	fromRound  string
	grantedAt  int64
}

func getGrant(addr string) *freeSpinGrant {
	if !casinoGrants.Has(addr) {
		return nil
	}
	return casinoGrants.Get(addr).(*freeSpinGrant)
}

func jpKey(coin, tier string) string { return coin + ":" + tier }

func jpRefBet(coin string) uint64 {
	if v := casGet(&casinoJpRef, coin); v > 0 {
		return v
	}
	return jpDefaultRefBet
}

// casinoJackpotContribute moves 1.0% / 0.5% of a paid slots stake from the house
// pool into the MAJOR / GRAND pools (remainders carried, nothing rounded away).
func casinoJackpotContribute(coin string, amt uint64) {
	for _, t := range [2]struct {
		tier string
		bps  uint64
	}{{"major", jpMajorBps}, {"grand", jpGrandBps}} {
		k := jpKey(coin, t.tier)
		dust := casAdd(casGet(&casinoJpDust, k), casMul(amt, t.bps))
		units := dust / 10000
		if units == 0 {
			casSet(&casinoJpDust, k, dust)
			continue
		}
		pool := casGet(&casinoPool, coin)
		if pool < casAdd(casGet(&casinoReserved, coin), units) {
			casSet(&casinoJpDust, k, dust) // house can't spare it right now: keep it owed
			continue
		}
		casSet(&casinoJpDust, k, dust%10000)
		casSet(&casinoPool, coin, pool-units)
		casSet(&casinoJackpot, k, casAdd(casGet(&casinoJackpot, k), units))
		day, snap, paid, recv := casinoDayState(coin)
		setCasinoDay(coin, day, snap, casAdd(paid, units), recv)
	}
}

// casinoJackpotPay pays a jackpot tier to addr: pool × min(1, bet/refBet).
func casinoJackpotPay(addr, coin, tier string, bet uint64) uint64 {
	k := jpKey(coin, tier)
	pool := casGet(&casinoJackpot, k)
	ref := jpRefBet(coin)
	pay := pool
	if bet < ref {
		pay = casMulDiv(pool, bet, ref)
	}
	casSet(&casinoJackpot, k, pool-pay)
	casCredit(addr, coin, pay)
	std.Emit("CasinoJackpotWon", "player", addr, "coin", coin, "tier", tier, "amount", casU(pay))
	// Top back up to the reset seed from the house pool, only if the house can easily afford it.
	seed := casGet(&casinoJpSeed, k)
	left := pool - pay
	if seed > left {
		need := seed - left
		house := casGet(&casinoPool, coin)
		reserved := casGet(&casinoReserved, coin)
		if house > reserved && house-reserved >= casMul(need, jpResetFreeMultiple) {
			casSet(&casinoPool, coin, house-need)
			casSet(&casinoJackpot, k, seed)
			day, snap, paid, recv := casinoDayState(coin)
			setCasinoDay(coin, day, snap, casAdd(paid, need), recv)
		}
	}
	return pay
}

// slotsHSPayout turns Hold & Spin tiles into bet multiples (under the cap) and
// the jackpot tiers won (paid from their pools).
func slotsHSPayout(tiles *[slotsCells]uint16, full bool) (uint64, bool, bool) {
	mult := uint64(0)
	major, grand := false, false
	for i := 0; i < slotsCells; i++ {
		v := tiles[i]
		switch {
		case v == 0:
		case v < 100:
			mult += uint64(v)
		case v == hsMini:
			mult += hsMiniMult
		case v == hsMinor:
			mult += hsMinorMult
		case v == hsMajor && !major:
			major = true
		case v == hsGrand && !grand:
			grand = true
		default: // a second MAJOR / GRAND in the same bonus pays as MINOR
			mult += hsMinorMult
		}
	}
	if full && !grand {
		grand = true
	}
	return mult, major, grand
}

// PlaceCasinoFreeSpin uses one free spin of the caller's grant in a committed
// round (no stake). One free spin in flight at a time.
func PlaceCasinoFreeSpin(cur realm, roundId string, clientHash string) {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	if isBlacklisted(caller) {
		panic("address banned")
	}
	r := mustCasinoRound(roundId)
	if r.player != caller {
		panic("this round belongs to another player")
	}
	if r.status != "committed" {
		panic("betting is closed for this round")
	}
	if time.Now().Unix()-r.committedAt >= casinoBetWindowSec {
		panic("round expired")
	}
	g := getGrant(caller)
	if g == nil || g.left == 0 {
		panic("no free spins left")
	}
	if g.inRound != "" {
		panic("a free spin is already in progress (round " + g.inRound + ")")
	}
	if !casIsHex64(clientHash) {
		panic("client hash must be sha256 hex")
	}
	g.inRound = roundId
	casinoBets.Set(roundId+":"+caller, &casinoBet{addr: caller, game: "slots", coin: g.coin, choice: "free", clientHash: clientHash, amount: g.bet, freeSpin: true})
	r.status = "bet"
	r.betAt = time.Now().Unix()
	r.bets = 1
}

// settleFreeSpin pays a free spin's win out of its grant's reservation.
func settleFreeSpin(b *casinoBet, win uint64) uint64 {
	g := getGrant(b.addr)
	if g == nil {
		panic("free spin grant missing")
	}
	if win > g.capLeft {
		win = g.capLeft
		b.capped = true
	}
	if win > 0 {
		casSet(&casinoReserved, b.coin, casSub(casGet(&casinoReserved, b.coin), win))
		casSet(&casinoPool, b.coin, casSub(casGet(&casinoPool, b.coin), win))
		day, snap, paid, recv := casinoDayState(b.coin)
		setCasinoDay(b.coin, day, snap, casAdd(paid, win), recv)
		casCredit(b.addr, b.coin, win)
	}
	g.capLeft -= win
	g.won += win
	g.left--
	g.inRound = ""
	if g.left == 0 {
		casSet(&casinoReserved, b.coin, casSub(casGet(&casinoReserved, b.coin), g.capLeft))
		casinoGrants.Remove(b.addr)
		std.Emit("CasinoFreeSpinsDone", "player", b.addr, "coin", b.coin, "won", casU(g.won))
	}
	return win
}

// FreeSpinGrant reports a player's open free spins (null when none).
func FreeSpinGrant(addr string) string {
	g := getGrant(addr)
	if g == nil {
		return "null"
	}
	return `{"coin":"` + g.coin + `","bet":` + casU(g.bet) + `,"left":` + casU(g.left) + `,"total":` + casU(g.total) +
		`,"mult":` + casU(freeSpinMult) + `,"capLeft":` + casU(g.capLeft) + `,"won":` + casU(g.won) +
		`,"inRound":"` + g.inRound + `","fromRound":"` + g.fromRound + `"}`
}

// CasinoJackpots reports the real MAJOR / GRAND pools and how they pay.
func CasinoJackpots(coinId string) string {
	return `{"coin":"` + coinId + `","major":"` + casU(casGet(&casinoJackpot, jpKey(coinId, "major"))) +
		`","grand":"` + casU(casGet(&casinoJackpot, jpKey(coinId, "grand"))) +
		`","majorSeed":"` + casU(casGet(&casinoJpSeed, jpKey(coinId, "major"))) +
		`","grandSeed":"` + casU(casGet(&casinoJpSeed, jpKey(coinId, "grand"))) +
		`","refBet":"` + casU(jpRefBet(coinId)) + `","miniMult":` + casU(hsMiniMult) + `,"minorMult":` + casU(hsMinorMult) +
		`,"majorBps":` + casU(jpMajorBps) + `,"grandBps":` + casU(jpGrandBps) + `}`
}

func validJpTier(tier string) bool { return tier == "major" || tier == "grand" }

// SeedCasinoJackpot adds the ADMIN'S OWN coins to a jackpot pool (never withdrawable).
func SeedCasinoJackpot(cur realm, coinId, tier, amount string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	if _, ok := coinRarity[coinId]; !ok {
		panic("unknown coin id: " + coinId)
	}
	if !validJpTier(tier) {
		panic("tier must be major or grand")
	}
	amt, err := strconv.ParseUint(amount, 10, 64)
	if err != nil || amt == 0 || amt > casinoMaxAmount {
		panic("invalid amount")
	}
	casDebit(admin.String(), coinId, amt)
	k := jpKey(coinId, tier)
	casSet(&casinoJackpot, k, casAdd(casGet(&casinoJackpot, k), amt))
	casStat(coinId, "", "seeded", amt)
	std.Emit("CasinoJackpotSeeded", "coin", coinId, "tier", tier, "amount", amount)
}

// SetCasinoJackpotSeed sets the level a jackpot is topped back up to after a hit.
func SetCasinoJackpotSeed(cur realm, coinId, tier, amount string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	if !validJpTier(tier) {
		panic("tier must be major or grand")
	}
	amt, err := strconv.ParseUint(amount, 10, 64)
	if err != nil || amt > casinoMaxAmount {
		panic("invalid amount")
	}
	casSet(&casinoJpSeed, jpKey(coinId, tier), amt)
}

// SetCasinoJackpotRefBet sets the bet that wins a full jackpot (smaller bets win
// the same share of the pool as their share of this bet).
func SetCasinoJackpotRefBet(cur realm, coinId, amount string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	amt, err := strconv.ParseUint(amount, 10, 64)
	if err != nil || amt == 0 || amt > casinoMaxAmount {
		panic("invalid amount")
	}
	casSet(&casinoJpRef, coinId, amt)
}

package game29

import (
	"std"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
	"time"
)

// ── rounds ──────────────────────────────────────────────────────────────────

func getCasinoRound(id string) *casinoRound {
	if !casinoRounds.Has(id) {
		return nil
	}
	r, ok := casinoRounds.Get(id).(*casinoRound)
	if !ok {
		return nil
	}
	return r
}

func mustCasinoRound(id string) *casinoRound {
	r := getCasinoRound(id)
	if r == nil {
		panic("round not found")
	}
	return r
}

func casinoRoundBet(r *casinoRound, roundId string) *casinoBet {
	key := roundId + ":" + r.player
	if !casinoBets.Has(key) {
		return nil
	}
	return casinoBets.Get(key).(*casinoBet)
}

// CommitCasinoSeed opens a round for one player with sha256(s). Operator only;
// a round id can be used once.
func CommitCasinoSeed(cur realm, roundId string, player string, seedHash string) {
	if !isOperator(cur) {
		panic("unauthorized: casino operator only")
	}
	if !casSafe(roundId, 64) {
		panic("invalid round id")
	}
	if casinoRounds.Has(roundId) {
		panic("round already exists")
	}
	if !address(player).IsValid() {
		panic("invalid player address")
	}
	seedHash = strings.ToLower(seedHash)
	if !casIsHex64(seedHash) {
		panic("seedHash must be sha256 hex")
	}
	casinoRounds.Set(roundId, &casinoRound{player: player, seedHash: seedHash, status: "committed", committedAt: time.Now().Unix()})
}

// PlaceCasinoBet escrows the player's bet with sha256(c): only the round's
// player, only before s is revealed, and only if the pool can pay its largest win.
func PlaceCasinoBet(cur realm, roundId string, game string, coinId string, betAmount string, choice string, clientHash string) {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	if isBlacklisted(caller) {
		panic("address banned")
	}
	r := mustCasinoRound(roundId)
	if r.player != caller {
		panic("this round belongs to another player")
	}
	if r.status != "committed" {
		panic("betting is closed for this round")
	}
	if time.Now().Unix()-r.committedAt >= casinoBetWindowSec {
		panic("round expired")
	}
	if _, ok := coinRarity[coinId]; !ok {
		panic("unknown coin id: " + coinId)
	}
	if !validCasinoChoice(game, choice) {
		panic("invalid game or choice: " + game + "/" + choice)
	}
	clientHash = strings.ToLower(clientHash)
	if !casIsHex64(clientHash) {
		panic("client hash must be sha256 hex")
	}
	amt, err := strconv.ParseUint(betAmount, 10, 64)
	if err != nil || amt == 0 || amt > casinoMaxAmount {
		panic("invalid bet amount")
	}
	if game == "slots" && getGrant(caller) != nil {
		panic("finish your free spins first")
	}
	// Check everything before any write, then debit and reserve the largest win.
	casinoCheckBet(coinId, game, amt)
	exp := casinoExposure(game, amt)
	casDebit(caller, coinId, amt)
	casinoReserve(coinId, exp)
	casinoBets.Set(roundId+":"+caller, &casinoBet{addr: caller, game: game, coin: coinId, choice: choice, clientHash: clientHash, amount: amt, exposure: exp})
	r.status = "bet"
	r.betAt = time.Now().Unix()
	r.bets = 1
}

// RevealCasinoSeed publishes s (it must hash to the commit). It settles nothing:
// the bet settles when the player's secret is revealed.
func RevealCasinoSeed(cur realm, roundId string, serverSeed string) {
	if !isOperator(cur) {
		panic("unauthorized: casino operator only")
	}
	r := mustCasinoRound(roundId)
	if r.status != "committed" && r.status != "bet" {
		panic("round already revealed or closed")
	}
	h := sha256.Sum256([]byte(serverSeed))
	if hex.EncodeToString(h[:]) != r.seedHash {
		panic("server seed does not match the committed hash")
	}
	r.serverSeed = serverSeed
	if r.status == "committed" {
		r.status = "closed" // no bet was placed: the round just ends
		return
	}
	r.status = "seeded"
	r.seededAt = time.Now().Unix()
}

// RevealCasinoSecret publishes the player's secret c (anyone may relay it: it
// must hash to the bet's hash) and settles the bet on chain. Works while paused.
func RevealCasinoSecret(cur realm, roundId string, clientSecret string) {
	r := mustCasinoRound(roundId)
	if r.status != "seeded" {
		panic("round is not waiting for the client secret")
	}
	b := casinoRoundBet(r, roundId)
	if b == nil || b.settled {
		panic("no open bet in this round")
	}
	if !casSafe(clientSecret, 64) {
		panic("invalid client secret")
	}
	if sha256Hex(clientSecret) != b.clientHash {
		panic("client secret does not match the bet's hash")
	}
	b.clientSecret = clientSecret
	casinoResolve(roundId, r, b)
	r.status = "settled"
}

// casinoResolve rolls the bet from s and c, pays it, and records the result.
func casinoResolve(roundId string, r *casinoRound, b *casinoBet) {
	payout := uint64(0)
	switch b.game {
	case "slots":
		s := newSlotsStream(r.serverSeed, b.clientSecret, roundId)
		g := slotsSpinGrid(s)
		mult, lines := slotsLineMult(&g)
		sc := slotsCount(&g, symScatter)
		win := casMul(b.amount/slotsBetStep, mult)
		if sc >= 3 {
			win = casAdd(win, casMul(b.amount, slotsScatterPay[sc]))
		}
		b.grid = slotsGridString(&g)
		b.lineMult = mult
		b.lines = lines
		b.scatters = sc
		if b.freeSpin {
			// ×2, no retrigger, no Hold & Spin; paid from the grant's reservation.
			payout = settleFreeSpin(b, casMul(win, freeSpinMult))
			b.payout = payout
			b.won = payout > 0
			b.outcome = "lose"
			if payout > 0 {
				b.outcome = "win"
			}
			b.settled = true
			casRecord(b.coin, "slots", 0, payout)
			casStat(b.coin, "slots", "freeSpins", 1)
			std.Emit("CasinoBetSettled", "round", roundId, "player", b.addr, "game", "slots", "coin", b.coin,
				"amount", "0", "freeSpin", "true", "outcome", b.outcome, "won", strconv.FormatBool(b.won), "payout", casU(payout))
			return
		}
		major, grand := false, false
		if slotsCount(&g, symVault) >= 3 {
			tiles, played, full := slotsHoldAndSpin(s, &g)
			hm, mj, gr := slotsHSPayout(&tiles, full)
			b.hsTiles = hsTilesString(&tiles)
			b.hsRespins = played
			b.hsMult = hm
			major, grand = mj, gr
			win = casAdd(win, casMul(b.amount, hm))
		}
		capWin := casMul(b.amount, slotsMaxWinMult)
		if win > capWin {
			win = capWin
			b.capped = true
		}
		payout = casinoSettle(b.addr, b.coin, b.amount, b.exposure, win)
		if sc >= 3 {
			// The rest of this spin's 500× cap stays reserved for its free spins
			// (reserved before anything else leaves the pool, so pool ≥ reserved holds).
			n := slotsFreeSpins[sc]
			capLeft := capWin - win
			casinoReserve(b.coin, capLeft)
			casinoGrants.Set(b.addr, &freeSpinGrant{addr: b.addr, coin: b.coin, bet: b.amount, left: n, total: n, capLeft: capLeft, fromRound: roundId, grantedAt: time.Now().Unix()})
			b.fsGranted = n
			std.Emit("CasinoFreeSpinsGranted", "player", b.addr, "coin", b.coin, "spins", casU(n), "bet", casU(b.amount))
		}
		casinoJackpotContribute(b.coin, b.amount)
		jw := uint64(0)
		if grand {
			jw = casAdd(jw, casinoJackpotPay(b.addr, b.coin, "grand", b.amount))
			b.jackpots = "grand"
		}
		if major {
			jw = casAdd(jw, casinoJackpotPay(b.addr, b.coin, "major", b.amount))
			if b.jackpots != "" {
				b.jackpots = "major+" + b.jackpots
			} else {
				b.jackpots = "major"
			}
		}
		b.jackpotWin = jw
		b.payout = casAdd(payout, jw)
		b.won = b.payout > b.amount
		b.outcome = "lose"
		if b.payout > 0 {
			b.outcome = "win"
		}
		b.settled = true
		casRecord(b.coin, "slots", b.amount, b.payout)
		std.Emit("CasinoBetSettled", "round", roundId, "player", b.addr, "game", "slots", "coin", b.coin,
			"amount", casU(b.amount), "outcome", b.outcome, "won", strconv.FormatBool(b.won), "payout", casU(b.payout),
			"jackpots", b.jackpots, "freeSpins", casU(b.fsGranted))
		return
	case "rps":
		b.roll = CasinoRoll(r.serverSeed, b.clientSecret, roundId, b.game)
		res := CasinoOutcome("rps", b.roll)
		b.outcome = rpsHouseMove(b.choice, res)
		switch res {
		case "win":
			payout = casAdd(b.amount, b.amount)
			b.won = true
		case "push":
			payout = b.amount
		}
	default:
		b.roll = CasinoRoll(r.serverSeed, b.clientSecret, roundId, b.game)
		b.outcome = CasinoOutcome(b.game, b.roll)
		if b.outcome == b.choice {
			payout = casAdd(b.amount, b.amount)
			b.won = true
		}
	}
	b.payout = casinoSettle(b.addr, b.coin, b.amount, b.exposure, payout)
	b.settled = true
	casRecord(b.coin, b.game, b.amount, b.payout)
	std.Emit("CasinoBetSettled", "round", roundId, "player", b.addr, "game", b.game, "coin", b.coin,
		"amount", casU(b.amount), "roll", casU(b.roll), "outcome", b.outcome, "won", strconv.FormatBool(b.won), "payout", casU(b.payout))
}

// RefundCasinoBet returns the stake only if s was never revealed and 30 minutes
// have passed since the bet. Never after s is revealed. Works while paused.
func RefundCasinoBet(cur realm, roundId string) {
	caller := cur.Previous().Address().String()
	r := mustCasinoRound(roundId)
	if r.status == "refunded" {
		panic("bet already settled")
	}
	if r.status != "bet" {
		panic("round already revealed: no refunds")
	}
	if r.player != caller {
		panic("no bet found for this round")
	}
	if time.Now().Unix()-r.betAt < casinoSeedTimeoutSec {
		panic("refund opens 30 minutes after the bet if the server seed is never revealed")
	}
	b := casinoRoundBet(r, roundId)
	b.settled = true
	b.refunded = true
	if b.freeSpin {
		// No stake was taken: the free spin goes back to the grant.
		if g := getGrant(caller); g != nil && g.inRound == roundId {
			g.inRound = ""
		}
	} else {
		casSet(&casinoReserved, b.coin, casSub(casGet(&casinoReserved, b.coin), b.exposure))
		casCredit(caller, b.coin, b.amount)
	}
	r.status = "refunded"
	std.Emit("CasinoBetRefunded", "round", roundId, "player", caller, "amount", casU(b.amount))
}

// ForfeitCasinoBet settles a bet as a loss when s was revealed but the player's
// secret was not within 24 h (only the player could know the result). Anyone.
func ForfeitCasinoBet(cur realm, roundId string) {
	r := mustCasinoRound(roundId)
	if r.status != "seeded" {
		panic("round is not waiting for the client secret")
	}
	if time.Now().Unix()-r.seededAt < casinoSecretTimeoutSec {
		panic("forfeit opens 24 hours after the server seed is revealed")
	}
	b := casinoRoundBet(r, roundId)
	b.forfeited = true
	b.outcome = "forfeit"
	if b.freeSpin {
		b.payout = settleFreeSpin(b, 0) // the free spin is used, it wins nothing
		casRecord(b.coin, b.game, 0, 0)
	} else {
		b.payout = casinoSettle(b.addr, b.coin, b.amount, b.exposure, 0)
		casRecord(b.coin, b.game, b.amount, 0)
	}
	b.settled = true
	r.status = "settled"
	std.Emit("CasinoBetForfeited", "round", roundId, "player", b.addr, "amount", casU(b.amount))
}

// ── queries ─────────────────────────────────────────────────────────────────

func CasinoRound(roundId string) string {
	r := getCasinoRound(roundId)
	if r == nil {
		return "null"
	}
	return `{"roundId":"` + roundId + `","player":"` + r.player + `","seedHash":"` + r.seedHash + `","serverSeed":"` + r.serverSeed +
		`","status":"` + r.status + `","committedAt":` + strconv.FormatInt(r.committedAt, 10) +
		`,"betAt":` + strconv.FormatInt(r.betAt, 10) + `,"seededAt":` + strconv.FormatInt(r.seededAt, 10) +
		`,"bets":` + strconv.Itoa(r.bets) + `}`
}

// CasinoBet returns one player's bet and its on-chain result.
func CasinoBet(roundId string, addr string) string {
	key := roundId + ":" + addr
	if !casinoBets.Has(key) {
		return "null"
	}
	b := casinoBets.Get(key).(*casinoBet)
	return `{"addr":"` + b.addr + `","game":"` + b.game + `","coinId":"` + b.coin + `","amount":` + casU(b.amount) +
		`,"exposure":` + casU(b.exposure) + `,"choice":"` + b.choice + `","clientHash":"` + b.clientHash +
		`","clientSecret":"` + b.clientSecret + `","clientSeed":"` + b.clientSecret + `","settled":` + strconv.FormatBool(b.settled) +
		`,"refunded":` + strconv.FormatBool(b.refunded) + `,"forfeited":` + strconv.FormatBool(b.forfeited) +
		`,"won":` + strconv.FormatBool(b.won) + `,"roll":` + casU(b.roll) + `,"outcome":"` + b.outcome +
		`","payout":` + casU(b.payout) + `,"grid":"` + b.grid + `","lineMult":` + casU(b.lineMult) +
		`,"lines":` + strconv.Itoa(b.lines) + `,"scatters":` + strconv.Itoa(b.scatters) +
		`,"freeSpin":` + strconv.FormatBool(b.freeSpin) + `,"capped":` + strconv.FormatBool(b.capped) +
		`,"fsGranted":` + casU(b.fsGranted) + `,"hsTiles":"` + b.hsTiles + `","hsRespins":` + strconv.Itoa(b.hsRespins) +
		`,"hsMult":` + casU(b.hsMult) + `,"jackpots":"` + b.jackpots + `","jackpotWin":` + casU(b.jackpotWin) + `}`
}

// JackpotPool reports the GRAND jackpot pool (the casino bankroll is CasinoPool).
func JackpotPool(coinId string) string {
	return `{"pool":"` + casU(casGet(&casinoJackpot, jpKey(coinId, "grand"))) + `","coinId":"` + coinId + `"}`
}

func CasinoHistory(_ string) string { return "[]" }

package game29

import (
	"sort"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// ── Guilds ───────────────────────────────────────────────────────────────────

const maxGuildMembers = 10
const maxGuildNameLen = 24

func guildJSON(guildId, name, leader string, members int, createdAt int64) string {
	return `{"guildId":` + jsonStr(guildId) + `,"name":` + jsonStr(name) + `,"leader":` + jsonStr(leader) +
		`,"memberCount":` + strconv.Itoa(members) + `,"createdAt":` + strconv.FormatInt(createdAt, 10) + `}`
}

func guildMemberCount(gid string) int {
	n := 0
	guildMembers.Iterate(gid+":", gid+";", func(string, any) bool {
		n++
		return false
	})
	return n
}

type guildMeta struct {
	name, leader string
	createdAt    int64
}

// guild meta is stored alongside the JSON so it can be re-rendered safely.
var guildMetas = map[string]guildMeta{}

func rewriteGuild(gid string) {
	m, ok := guildMetas[gid]
	if !ok {
		return
	}
	guilds.Set(gid, guildJSON(gid, m.name, m.leader, guildMemberCount(gid), m.createdAt))
}

func CreateGuild(cur realm, name string) string {
	caller := requirePlayer(cur)
	if playerGuild.Has(caller) {
		panic("already in a guild")
	}
	name = sanitizeName(name)
	if len(name) < 3 {
		panic("guild name too short (min 3 chars)")
	}
	if len(name) > maxGuildNameLen {
		panic("guild name too long (max 24 chars)")
	}
	guildCounter++
	gid := "guild-" + zeroPad(guildCounter, 6)
	now := time.Now().Unix()
	guildMetas[gid] = guildMeta{name: name, leader: caller, createdAt: now}
	guildMembers.Set(gid+":"+caller, "1")
	playerGuild.Set(caller, gid)
	rewriteGuild(gid)
	return gid
}

func JoinGuild(cur realm, guildId string) {
	caller := requirePlayer(cur)
	if playerGuild.Has(caller) {
		panic("already in a guild — leave current guild first")
	}
	if !guilds.Has(guildId) {
		panic("guild not found")
	}
	if guildMemberCount(guildId) >= maxGuildMembers {
		panic("guild is full (max 10 members)")
	}
	guildMembers.Set(guildId+":"+caller, "1")
	playerGuild.Set(caller, guildId)
	rewriteGuild(guildId)
}

func LeaveGuild(cur realm) {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	if !playerGuild.Has(caller) {
		panic("not in a guild")
	}
	gid := playerGuild.Get(caller).(string)
	guildMembers.Remove(gid + ":" + caller)
	playerGuild.Remove(caller)
	if guildMemberCount(gid) == 0 {
		guilds.Remove(gid)
		delete(guildMetas, gid)
		return
	}
	if m, ok := guildMetas[gid]; ok && m.leader == caller {
		// hand leadership to the first remaining member
		guildMembers.Iterate(gid+":", gid+";", func(k string, _ any) bool {
			m.leader = strings.TrimPrefix(k, gid+":")
			return true
		})
		guildMetas[gid] = m
	}
	rewriteGuild(gid)
}

func PlayerGuild(addr string) string {
	if !playerGuild.Has(addr) {
		return ""
	}
	gid := playerGuild.Get(addr).(string)
	if !guilds.Has(gid) {
		return ""
	}
	return guilds.Get(gid).(string)
}

func GuildInfo(guildId string) string {
	if !guilds.Has(guildId) {
		return ""
	}
	return guilds.Get(guildId).(string)
}

func TopGuilds(limit int) string {
	if limit <= 0 || limit > 50 {
		limit = 20
	}
	var all guildRows
	guilds.Iterate("", "", func(k string, v any) bool {
		all = append(all, guildRow{v.(string), guildMemberCount(k)})
		return false
	})
	sort.Stable(all)
	var parts []string
	for i := 0; i < len(all) && i < limit; i++ {
		parts = append(parts, all[i].js)
	}
	return "[" + strings.Join(parts, ",") + "]"
}

// ── Queries ──────────────────────────────────────────────────────────────────

func kvJSON(prefixAddr string, t *avl.Tree) string {
	var parts []string
	t.Iterate(prefixAddr+":", prefixAddr+";", func(key string, val any) bool {
		parts = append(parts, jsonStr(strings.TrimPrefix(key, prefixAddr+":"))+":"+val.(string))
		return false
	})
	return "{" + strings.Join(parts, ",") + "}"
}

func AllBalances(playerAddr string) string   { return kvJSON(playerAddr, &balances) }
func LifetimeMined(playerAddr string) string { return kvJSON(playerAddr, &lifetimeMined) }

// PlayerXp returns the caller's cumulative rarity-weighted XP earned from
// ClaimAndMint calls as a plain decimal string (e.g. "12345"). Returns "0"
// for players who have not yet minted anything on this realm version.
func PlayerXp(playerAddr string) string {
	return strconv.FormatUint(getU(&playerXp, playerAddr), 10)
}

// Rewarded returns what rewards (medals etc.) credited, per coin. Separate
// from LifetimeMined.
func Rewarded(playerAddr string) string { return kvJSON(playerAddr, &rewarded) }
func SkillRanks(playerAddr string) string    { return kvJSON(playerAddr, &skillRanks) }
